#[derive(Debug)]
struct RuntimeBackfillInvariant(String);

impl std::fmt::Display for RuntimeBackfillInvariant {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for RuntimeBackfillInvariant {}

fn runtime_backfill_sql_error(message: impl Into<String>) -> rusqlite::Error {
    rusqlite::Error::ToSqlConversionFailure(Box::new(RuntimeBackfillInvariant(message.into())))
}

fn model_backfill_sql_error(message: impl Into<String>) -> rusqlite::Error {
    rusqlite::Error::ToSqlConversionFailure(Box::new(RuntimeBackfillInvariant(message.into())))
}

struct CurrentModelSourceSuppression {
    processing_status: String,
    suppressed_sha256: Option<String>,
    content_sha256: Option<String>,
    last_success_at_ms: Option<i64>,
    observation_count: i64,
    has_observations: bool,
}

/// Classify one source in two stages: callers omit `content_sha256` before
/// reading, then call again with the hash of those exact bytes when required.
pub(crate) fn classify_model_source_change(
    existing: Option<&StoredModelSource>,
    fast: ModelSourceFastFingerprint,
    content_sha256: Option<&str>,
) -> ModelSourceChange {
    let Some(existing) = existing else {
        return if content_sha256.is_some() {
            ModelSourceChange::ContentChanged
        } else {
            ModelSourceChange::ContentHashRequired
        };
    };

    let is_suppressed = existing.processing_status == SourceProcessingStatus::Suppressed
        || existing.suppressed_sha256.is_some();
    if !is_suppressed
        && existing.processing_status == SourceProcessingStatus::Ok
        && existing.fast_fingerprint == Some(fast)
    {
        return ModelSourceChange::FastUnchanged;
    }

    let Some(content_sha256) = content_sha256 else {
        return ModelSourceChange::ContentHashRequired;
    };

    if is_suppressed {
        return if existing.suppressed_sha256.as_deref() == Some(content_sha256) {
            ModelSourceChange::SuppressedUnchanged
        } else {
            ModelSourceChange::SuppressedChanged
        };
    }

    if existing.content_sha256.as_deref() == Some(content_sha256) {
        ModelSourceChange::ContentUnchanged
    } else {
        ModelSourceChange::ContentChanged
    }
}

fn read_raw_model_source(row: &rusqlite::Row<'_>) -> rusqlite::Result<RawStoredModelSource> {
    Ok(RawStoredModelSource {
        source_key: row.get(0)?,
        source_root_key: row.get(1)?,
        source_path: row.get(2)?,
        source_session_id: row.get(3)?,
        analytics_session_id: row.get(4)?,
        chain_id: row.get(5)?,
        parent_chain_id: row.get(6)?,
        agent_id: row.get(7)?,
        agent_nickname: row.get(8)?,
        is_sidechain: row.get(9)?,
        cwd: row.get(10)?,
        hostname: row.get(11)?,
        first_activity_at_ms: row.get(12)?,
        last_activity_at_ms: row.get(13)?,
        mtime_ns: row.get(14)?,
        size_bytes: row.get(15)?,
        content_sha256: row.get(16)?,
        last_error: row.get(17)?,
        suppressed_sha256: row.get(18)?,
        suppressed_at_ms: row.get(19)?,
        seen_generation: row.get(20)?,
        processing_status: row.get(21)?,
        observation_count: row.get(22)?,
        last_attempt_at_ms: row.get(23)?,
        last_success_at_ms: row.get(24)?,
    })
}

fn stored_model_source_from_raw(
    provider: IntegrationProvider,
    row: RawStoredModelSource,
) -> Result<StoredModelSource, String> {
    let fast_fingerprint = match (row.mtime_ns, row.size_bytes) {
        (Some(mtime_ns), Some(size_bytes)) => {
            validate_nonnegative_model_source_value(mtime_ns, "mtime_ns")?;
            validate_nonnegative_model_source_value(size_bytes, "size_bytes")?;
            Some(ModelSourceFastFingerprint {
                mtime_ns,
                size_bytes,
            })
        }
        (None, None) => None,
        _ => {
            return Err(format!(
                "Model source {} has an incomplete fast fingerprint",
                row.source_key
            ));
        }
    };
    let is_sidechain = match row.is_sidechain {
        0 => false,
        1 => true,
        value => {
            return Err(format!(
                "Model source {} has invalid is_sidechain value {value}",
                row.source_key
            ));
        }
    };
    let processing_status = SourceProcessingStatus::try_from(row.processing_status.as_str())
        .map_err(|error| format!("Model source {} {error}", row.source_key))?;
    validate_nonnegative_model_source_value(row.seen_generation, "seen_generation")?;
    validate_nonnegative_model_source_value(row.observation_count, "observation_count")?;
    validate_optional_model_source_value(row.first_activity_at_ms, "first_activity_at_ms")?;
    validate_optional_model_source_value(row.last_activity_at_ms, "last_activity_at_ms")?;
    validate_optional_model_source_value(row.suppressed_at_ms, "suppressed_at_ms")?;
    validate_optional_model_source_value(row.last_attempt_at_ms, "last_attempt_at_ms")?;
    validate_optional_model_source_value(row.last_success_at_ms, "last_success_at_ms")?;
    if let (Some(first), Some(last)) = (row.first_activity_at_ms, row.last_activity_at_ms)
        && first > last
    {
        return Err(format!(
            "Model source {} first activity exceeds last activity",
            row.source_key
        ));
    }
    let source_path = model_source_path_from_storage(&row.source_path)?;

    Ok(StoredModelSource {
        provider,
        source_key: row.source_key,
        source_root_key: row.source_root_key,
        source_path,
        fast_fingerprint,
        content_sha256: row.content_sha256,
        processing_status,
        last_error: row
            .last_error
            .map(|message| ModelUsageDiagnostic::from_user_safe_message(&message)),
        suppressed_sha256: row.suppressed_sha256,
        suppressed_at_ms: row.suppressed_at_ms,
        seen_generation: row.seen_generation,
        last_attempt_at_ms: row.last_attempt_at_ms,
        last_good: ModelSourceLastGoodMetadata {
            source_session_id: row.source_session_id,
            analytics_session_id: row.analytics_session_id,
            chain_id: row.chain_id,
            parent_chain_id: row.parent_chain_id,
            agent_id: row.agent_id,
            agent_nickname: row.agent_nickname,
            is_sidechain,
            cwd: row.cwd.map(PathBuf::from),
            hostname: row.hostname,
            first_activity_at_ms: row.first_activity_at_ms,
            last_activity_at_ms: row.last_activity_at_ms,
            observation_count: row.observation_count,
            last_success_at_ms: row.last_success_at_ms,
        },
    })
}

fn validate_nonnegative_model_source_value(value: i64, field: &str) -> Result<(), String> {
    if value < 0 {
        Err(format!("Model source {field} cannot be negative: {value}"))
    } else {
        Ok(())
    }
}

fn validate_optional_model_source_value(value: Option<i64>, field: &str) -> Result<(), String> {
    if let Some(value) = value {
        validate_nonnegative_model_source_value(value, field)?;
    }
    Ok(())
}

fn model_source_path_for_storage(path: &Path) -> Result<String, String> {
    #[cfg(unix)]
    {
        Ok(format!(
            "{MODEL_SOURCE_PATH_UNIX_PREFIX}{}",
            crate::hex_encode(path.as_os_str().as_bytes())
        ))
    }

    #[cfg(windows)]
    {
        let bytes = path
            .as_os_str()
            .encode_wide()
            .flat_map(|unit| unit.to_le_bytes())
            .collect::<Vec<_>>();
        Ok(format!(
            "{MODEL_SOURCE_PATH_WINDOWS_PREFIX}{}",
            crate::hex_encode(bytes)
        ))
    }

    #[cfg(not(any(unix, windows)))]
    {
        let value = path
            .to_str()
            .ok_or_else(|| "Model source path is not valid Unicode".to_string())?;
        Ok(format!("{MODEL_SOURCE_PATH_UNICODE_PREFIX}{value}"))
    }
}

fn model_source_path_from_storage(value: &str) -> Result<PathBuf, String> {
    if let Some(encoded) = value.strip_prefix(MODEL_SOURCE_PATH_UNIX_PREFIX) {
        #[cfg(unix)]
        {
            let bytes = crate::hex_decode(encoded)
                .map_err(|error| format!("Decode Unix model source path: {error}"))?;
            return Ok(PathBuf::from(OsString::from_vec(bytes)));
        }
        #[cfg(not(unix))]
        {
            let _ = encoded;
            return Err("Cannot decode a Unix model source path on this platform".to_string());
        }
    }

    if let Some(encoded) = value.strip_prefix(MODEL_SOURCE_PATH_WINDOWS_PREFIX) {
        #[cfg(windows)]
        {
            let bytes = crate::hex_decode(encoded)
                .map_err(|error| format!("Decode Windows model source path: {error}"))?;
            let mut chunks = bytes.chunks_exact(2);
            let wide = chunks
                .by_ref()
                .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
                .collect::<Vec<_>>();
            if !chunks.remainder().is_empty() {
                return Err("Decode Windows model source path: odd UTF-16 byte count".to_string());
            }
            return Ok(PathBuf::from(OsString::from_wide(&wide)));
        }
        #[cfg(not(windows))]
        {
            let _ = encoded;
            return Err("Cannot decode a Windows model source path on this platform".to_string());
        }
    }

    if let Some(value) = value.strip_prefix(MODEL_SOURCE_PATH_UNICODE_PREFIX) {
        return Ok(PathBuf::from(value));
    }

    // Migration-28 rows written before exact path encoding used plain Unicode.
    Ok(PathBuf::from(value))
}

fn model_source_cwd_for_storage(path: &Path) -> Result<String, String> {
    path.to_str()
        .map(str::to_owned)
        .ok_or_else(|| "Model source cwd is not valid Unicode".to_string())
}

fn validate_normalized_model_source(source: &NormalizedSource) -> Result<(), String> {
    if source.source_key.is_empty() {
        return Err("Model source key cannot be empty".to_string());
    }
    if source.source_root_key.is_empty() {
        return Err("Model source root key cannot be empty".to_string());
    }

    validate_nonnegative_model_source_value(source.seen_generation, "seen_generation")?;
    validate_nonnegative_model_source_value(source.observation_count, "observation_count")?;
    validate_optional_model_source_value(source.first_activity_at_ms, "first_activity_at_ms")?;
    validate_optional_model_source_value(source.last_activity_at_ms, "last_activity_at_ms")?;
    validate_optional_model_source_value(source.mtime_ns, "mtime_ns")?;
    validate_optional_model_source_value(source.size_bytes, "size_bytes")?;
    validate_optional_model_source_value(source.suppressed_at_ms, "suppressed_at_ms")?;
    validate_optional_model_source_value(source.last_attempt_at_ms, "last_attempt_at_ms")?;
    validate_optional_model_source_value(source.last_success_at_ms, "last_success_at_ms")?;

    if let (Some(first), Some(last)) = (source.first_activity_at_ms, source.last_activity_at_ms)
        && first > last
    {
        return Err(format!(
            "Model source first_activity_at_ms {first} exceeds last_activity_at_ms {last}"
        ));
    }

    Ok(())
}

fn validate_model_source_fingerprint(
    source: &NormalizedSource,
    fingerprint: &ModelSourceFingerprint,
) -> Result<(), String> {
    let fast = fingerprint.fast();
    if source
        .mtime_ns
        .is_some_and(|value| value != fast.mtime_ns())
    {
        return Err("Normalized source mtime does not match replacement fingerprint".to_string());
    }
    if source
        .size_bytes
        .is_some_and(|value| value != fast.size_bytes())
    {
        return Err("Normalized source size does not match replacement fingerprint".to_string());
    }
    if source
        .content_sha256
        .as_deref()
        .is_some_and(|value| value != fingerprint.content_sha256())
    {
        return Err("Normalized source hash does not match replacement fingerprint".to_string());
    }

    Ok(())
}

fn prepare_model_observations<'a>(
    source: &NormalizedSource,
    observations: &'a [NormalizedObservation],
) -> Result<Vec<PreparedModelObservation<'a>>, String> {
    let observation_count = i64::try_from(observations.len())
        .map_err(|_| "Model source observation count exceeds SQLite INTEGER range".to_string())?;
    if source.observation_count != observation_count {
        return Err(format!(
            "Normalized source observation_count {} does not match parsed count {observation_count}",
            source.observation_count
        ));
    }

    observations
        .iter()
        .map(|observation| {
            let metadata = observation.metadata();
            if metadata.provider != source.provider {
                return Err(format!(
                    "Model observation provider {} does not match source provider {}",
                    metadata.provider.as_str(),
                    source.provider.as_str()
                ));
            }
            if metadata.source_key != source.source_key {
                return Err(format!(
                    "Model observation source key {} does not match source key {}",
                    metadata.source_key, source.source_key
                ));
            }
            validate_nonnegative_model_source_value(
                metadata.observed_at_ms,
                "observation observed_at_ms",
            )?;
            let source_ordinal = i64::try_from(metadata.source_ordinal).map_err(|_| {
                format!(
                    "Model observation source ordinal {} exceeds SQLite INTEGER range",
                    metadata.source_ordinal
                )
            })?;

            Ok(PreparedModelObservation {
                observation,
                source_ordinal,
                cwd: metadata
                    .cwd
                    .as_deref()
                    .map(model_source_cwd_for_storage)
                    .transpose()?,
            })
        })
        .collect()
}

// @lat: [[backend#Backend#Database#Schema#Hourly Analytics Rollups]]
fn refold_runtime_source(
    tx: &rusqlite::Transaction<'_>,
    source: &crate::transcript_analytics::TranscriptAnalyticsSourceState,
) -> Result<(), String> {
    refold_runtime_source_identity(
        tx,
        source.provider.as_str(),
        &source.source_key,
        &source.analytics_session_id,
        &source.chain_id,
    )
}

pub(crate) fn refold_runtime_source_identity(
    tx: &rusqlite::Transaction<'_>,
    provider: &str,
    source_key: &str,
    session_id: &str,
    chain_id: &str,
) -> Result<(), String> {
    let mut events = {
        let mut statement = tx
            .prepare(
                "SELECT rowid, timestamp, kind, session_id, chain_id
                 FROM session_events
                 WHERE provider = ?1 AND source_key = ?2",
            )
            .map_err(|error| format!("Prepare runtime source refold: {error}"))?;
        let rows = statement
            .query_map(params![provider, source_key], |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                ))
            })
            .map_err(|error| format!("Query runtime source refold: {error}"))?;
        let mut events = Vec::new();
        for row in rows {
            let (rowid, timestamp, kind, event_session_id, event_chain_id) =
                row.map_err(|error| format!("Read runtime source event: {error}"))?;
            if event_session_id != session_id {
                return Err(format!(
                    "Runtime event session {event_session_id} does not match source session {session_id}"
                ));
            }
            if event_chain_id != chain_id {
                return Err(format!(
                    "Runtime event chain {event_chain_id} does not match source chain {chain_id}"
                ));
            }
            let Ok(timestamp) = DateTime::parse_from_rfc3339(&timestamp) else {
                continue;
            };
            let timestamp_ms = timestamp.timestamp_millis();
            if timestamp_ms < 0 {
                return Err(format!(
                    "Runtime event row {rowid} timestamp predates the Unix epoch"
                ));
            }
            events.push(PersistedRuntimeEvent {
                rowid,
                timestamp_ms,
                kind,
            });
        }
        events
    };
    events.sort_unstable_by_key(|event| (event.timestamp_ms, event.rowid));

    let deleted_rollup_rows = tx
        .execute(
            "DELETE FROM runtime_hourly
             WHERE provider = ?1 AND source_key = ?2 AND raw_pruned = 0",
            params![provider, source_key],
        )
        .map_err(|error| format!("Delete replaced runtime rollup rows: {error}"))?;
    let deleted_state_rows = tx
        .execute(
            "DELETE FROM runtime_turn_state
             WHERE provider = ?1 AND source_key = ?2",
            params![provider, source_key],
        )
        .map_err(|error| format!("Delete replaced runtime turn state: {error}"))?;

    let fold = fold_persisted_runtime_events(&events, "Runtime source refold")?;

    let mut folded_rollup_rows = 0_usize;
    if !fold.rollups.is_empty() {
        let mut statement = tx
            .prepare_cached(
                "INSERT INTO runtime_hourly (
                     hour_utc, provider, source_key, session_id, turn_count,
                     runtime_secs, first_turn_start_ms, last_turn_end_ms,
                     raw_pruned
                 ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, 0)
                 ON CONFLICT(hour_utc, provider, source_key) DO UPDATE SET
                     session_id = excluded.session_id,
                     turn_count = excluded.turn_count,
                     runtime_secs = excluded.runtime_secs,
                     first_turn_start_ms = excluded.first_turn_start_ms,
                     last_turn_end_ms = excluded.last_turn_end_ms
                 WHERE runtime_hourly.raw_pruned = 0",
            )
            .map_err(|error| format!("Prepare runtime hourly refold: {error}"))?;
        for rollup in &fold.rollups {
            folded_rollup_rows += statement
                .execute(params![
                    rollup.hour_utc,
                    provider,
                    source_key,
                    session_id,
                    rollup.turn_count,
                    rollup.runtime_millis as f64 / 1_000.0,
                    rollup.first_turn_start_ms,
                    rollup.last_turn_end_ms,
                ])
                .map_err(|error| format!("UPSERT runtime hourly refold: {error}"))?;
        }
    }

    let inserted_state_rows = if let Some(open_turn_started_ms) = fold.open_turn_started_ms {
        tx.execute(
            "INSERT INTO runtime_turn_state (
                 provider, source_key, finalized_through_rowid,
                 open_turn_started_ms
             ) VALUES (?1, ?2, ?3, ?4)",
            params![
                provider,
                source_key,
                fold.finalized_through_rowid,
                open_turn_started_ms,
            ],
        )
        .map_err(|error| format!("Insert runtime turn state: {error}"))?
    } else {
        0
    };

    if deleted_rollup_rows > 0
        || deleted_state_rows > 0
        || folded_rollup_rows > 0
        || inserted_state_rows > 0
    {
        let updated = tx
            .execute(
                "UPDATE rollup_meta
                 SET rollup_generation = rollup_generation + 1
                 WHERE id = 1",
                [],
            )
            .map_err(|error| format!("Bump runtime rollup generation: {error}"))?;
        if updated != 1 {
            return Err("Runtime rollup metadata singleton is missing".to_string());
        }
    }

    Ok(())
}

// @lat: [[backend#Backend#Database#Schema#Hourly Analytics Rollups]]
pub(crate) fn verify_runtime_rollup_source_coverage(
    tx: &rusqlite::Transaction<'_>,
    provider: &str,
    source_key: &str,
) -> Result<i64, String> {
    let (session_id, chain_id) = tx
        .query_row(
            "SELECT analytics_session_id, chain_id
             FROM transcript_analytics_sources
             WHERE provider = ?1 AND source_key = ?2",
            params![provider, source_key],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
        )
        .map_err(|error| format!("Read runtime retention source identity: {error}"))?;
    let mut events = {
        let mut statement = tx
            .prepare(
                "SELECT rowid, timestamp, kind, session_id, chain_id
                 FROM session_events
                 WHERE provider = ?1 AND source_key = ?2
                 ORDER BY timestamp, rowid",
            )
            .map_err(|error| format!("Prepare runtime retention coverage: {error}"))?;
        let rows = statement
            .query_map(params![provider, source_key], |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                ))
            })
            .map_err(|error| format!("Query runtime retention coverage: {error}"))?;
        let mut events = Vec::new();
        for row in rows {
            let (rowid, timestamp, kind, event_session_id, event_chain_id) =
                row.map_err(|error| format!("Read runtime retention event: {error}"))?;
            if event_session_id != session_id || event_chain_id != chain_id {
                return Err(format!(
                    "Runtime retention source {provider}/{source_key} has mixed session or chain identity"
                ));
            }
            let Ok(timestamp) = DateTime::parse_from_rfc3339(&timestamp) else {
                continue;
            };
            let timestamp_ms = timestamp.timestamp_millis();
            if timestamp_ms < 0 {
                return Err(format!(
                    "Runtime retention event row {rowid} predates the Unix epoch"
                ));
            }
            events.push(PersistedRuntimeEvent {
                rowid,
                timestamp_ms,
                kind,
            });
        }
        events
    };
    events.sort_unstable_by_key(|event| (event.timestamp_ms, event.rowid));
    let fold = fold_persisted_runtime_events(&events, "Runtime retention coverage")?;

    let mut authoritative_hours = HashSet::new();
    let mut actual = BTreeMap::new();
    {
        let mut statement = tx
            .prepare(
                "SELECT hour_utc, session_id, turn_count, runtime_secs,
                        first_turn_start_ms, last_turn_end_ms, raw_pruned
                 FROM runtime_hourly
                 WHERE provider = ?1 AND source_key = ?2",
            )
            .map_err(|error| format!("Prepare runtime retention rollup read: {error}"))?;
        let rows = statement
            .query_map(params![provider, source_key], |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, i64>(2)?,
                    row.get::<_, f64>(3)?,
                    row.get::<_, i64>(4)?,
                    row.get::<_, i64>(5)?,
                    row.get::<_, i64>(6)?,
                ))
            })
            .map_err(|error| format!("Query runtime retention rollups: {error}"))?;
        for row in rows {
            let (hour, row_session_id, turns, seconds, first, last, raw_pruned) =
                row.map_err(|error| format!("Read runtime retention rollup: {error}"))?;
            if row_session_id != session_id {
                return Err(format!(
                    "Runtime retention rollup {provider}/{source_key}/{hour} has the wrong session identity"
                ));
            }
            if raw_pruned == 1 {
                authoritative_hours.insert(hour);
            } else {
                actual.insert(
                    hour,
                    (turns, (seconds * 1_000.0).round() as i64, first, last),
                );
            }
        }
    }
    let expected = fold
        .rollups
        .iter()
        .filter(|rollup| !authoritative_hours.contains(&rollup.hour_utc))
        .map(|rollup| {
            (
                rollup.hour_utc,
                (
                    rollup.turn_count,
                    rollup.runtime_millis,
                    rollup.first_turn_start_ms,
                    rollup.last_turn_end_ms,
                ),
            )
        })
        .collect::<BTreeMap<_, _>>();
    if actual != expected {
        return Err(format!(
            "Runtime rollup coverage does not match raw refold for {provider}/{source_key}: actual={actual:?}, expected={expected:?}"
        ));
    }

    let state = tx
        .query_row(
            "SELECT finalized_through_rowid, open_turn_started_ms
             FROM runtime_turn_state
             WHERE provider = ?1 AND source_key = ?2",
            params![provider, source_key],
            |row| Ok((row.get::<_, i64>(0)?, row.get::<_, Option<i64>>(1)?)),
        )
        .optional()
        .map_err(|error| format!("Read runtime retention bookmark: {error}"))?;
    let Some((finalized_through_rowid, open_turn_started_ms)) = state else {
        if events.is_empty() {
            return Ok(0);
        }
        return Err(format!(
            "Runtime rollup coverage is missing the bookmark for {provider}/{source_key}"
        ));
    };
    if finalized_through_rowid < fold.finalized_through_rowid
        || open_turn_started_ms != fold.open_turn_started_ms
    {
        return Err(format!(
            "Runtime rollup bookmark does not cover the raw refold for {provider}/{source_key}"
        ));
    }
    Ok(finalized_through_rowid)
}

pub(crate) fn seal_runtime_open_turn_for_retention(
    tx: &rusqlite::Transaction<'_>,
    provider: &str,
    source_key: &str,
    cutoff_ms: i64,
) -> Result<usize, String> {
    let state = tx
        .query_row(
            "SELECT state.finalized_through_rowid, state.open_turn_started_ms,
                    source.analytics_session_id
             FROM runtime_turn_state AS state
             JOIN transcript_analytics_sources AS source
               ON source.provider = state.provider
              AND source.source_key = state.source_key
             WHERE state.provider = ?1 AND state.source_key = ?2",
            params![provider, source_key],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, Option<i64>>(1)?,
                    row.get::<_, String>(2)?,
                ))
            },
        )
        .optional()
        .map_err(|error| format!("Read runtime retention open state: {error}"))?;
    let Some((finalized_through_rowid, Some(open_turn_started_ms), session_id)) = state else {
        return Ok(0);
    };
    let mut open_events = {
        let mut statement = tx
            .prepare(
                "SELECT rowid, timestamp, kind
                 FROM session_events
                 WHERE provider = ?1 AND source_key = ?2
                   AND rowid > ?3
                 ORDER BY timestamp, rowid",
            )
            .map_err(|error| format!("Prepare runtime retention open tail: {error}"))?;
        let rows = statement
            .query_map(
                params![provider, source_key, finalized_through_rowid],
                |row| {
                    Ok((
                        row.get::<_, i64>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, String>(2)?,
                    ))
                },
            )
            .map_err(|error| format!("Query runtime retention open tail: {error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("Read runtime retention open tail: {error}"))?
    };
    if open_events.is_empty() {
        return Err(format!(
            "Runtime retention open state for {provider}/{source_key} has no raw events"
        ));
    }
    let mut last_event_ms = 0_i64;
    for (_, timestamp, _) in &open_events {
        if !crate::retention::is_conforming_timestamp(timestamp) {
            return Ok(0);
        }
        let timestamp_ms = DateTime::parse_from_rfc3339(timestamp)
            .map_err(|error| format!("Parse runtime retention open timestamp: {error}"))?
            .timestamp_millis();
        if timestamp_ms >= cutoff_ms {
            return Ok(0);
        }
        last_event_ms = timestamp_ms;
    }
    let (_, _, last_kind) = open_events
        .last()
        .expect("non-empty runtime retention open tail");
    let turn_end_ms = if last_kind == "asst_tool_use" {
        last_event_ms.saturating_add(RUNTIME_TOOL_WAIT_MAX_MS)
    } else {
        last_event_ms
    };
    if turn_end_ms > cutoff_ms {
        return Ok(0);
    }
    let mut changed = 0_usize;
    if turn_end_ms > open_turn_started_ms {
        let hour_utc = open_turn_started_ms.div_euclid(MODEL_ROLLUP_HOUR_MS) * MODEL_ROLLUP_HOUR_MS;
        changed = changed.saturating_add(
            tx.execute(
                "INSERT INTO runtime_hourly (
                     hour_utc, provider, source_key, session_id, turn_count,
                     runtime_secs, first_turn_start_ms, last_turn_end_ms,
                     raw_pruned
                 ) VALUES (?1, ?2, ?3, ?4, 1, ?5, ?6, ?7, 0)
                 ON CONFLICT(hour_utc, provider, source_key) DO UPDATE SET
                     session_id = excluded.session_id,
                     turn_count = runtime_hourly.turn_count + 1,
                     runtime_secs = runtime_hourly.runtime_secs + excluded.runtime_secs,
                     first_turn_start_ms = MIN(
                         runtime_hourly.first_turn_start_ms,
                         excluded.first_turn_start_ms
                     ),
                     last_turn_end_ms = MAX(
                         runtime_hourly.last_turn_end_ms,
                         excluded.last_turn_end_ms
                     )",
                params![
                    hour_utc,
                    provider,
                    source_key,
                    session_id,
                    (turn_end_ms - open_turn_started_ms) as f64 / 1_000.0,
                    open_turn_started_ms,
                    turn_end_ms,
                ],
            )
            .map_err(|error| format!("Seal runtime retention open turn: {error}"))?,
        );
    }
    let max_open_rowid = open_events
        .drain(..)
        .map(|(rowid, _, _)| rowid)
        .max()
        .unwrap_or(finalized_through_rowid);
    changed = changed.saturating_add(
        tx.execute(
            "UPDATE runtime_turn_state
             SET finalized_through_rowid = MAX(finalized_through_rowid, ?3),
                 open_turn_started_ms = NULL
             WHERE provider = ?1 AND source_key = ?2",
            params![provider, source_key, max_open_rowid],
        )
        .map_err(|error| format!("Seal runtime retention open state: {error}"))?,
    );
    Ok(changed)
}

impl ModelRollupBackfillTarget {
    fn prepare_range(
        conn: &Connection,
        after_ms: i64,
        max_rows: u64,
    ) -> rusqlite::Result<Option<PreparedModelBackfillRange>> {
        let first_ms = conn
            .query_row(
                "SELECT observed_at_ms
                 FROM model_usage_observations
                 WHERE observed_at_ms > ?1
                 ORDER BY observed_at_ms
                 LIMIT 1",
                params![after_ms],
                |row| row.get::<_, i64>(0),
            )
            .optional()?;
        let Some(first_ms) = first_ms else {
            return Ok(None);
        };
        let offset = i64::try_from(max_rows.saturating_sub(1)).map_err(|_| {
            model_backfill_sql_error("Model backfill chunk row limit exceeds SQLite INTEGER range")
        })?;
        let boundary_ms = conn
            .query_row(
                "SELECT observed_at_ms
                 FROM model_usage_observations
                 WHERE observed_at_ms > ?1
                 ORDER BY observed_at_ms
                 LIMIT 1 OFFSET ?2",
                params![after_ms, offset],
                |row| row.get::<_, i64>(0),
            )
            .optional()?;
        let boundary_ms = match boundary_ms {
            Some(boundary_ms) => boundary_ms,
            None => conn
                .query_row(
                    "SELECT MAX(observed_at_ms)
                     FROM model_usage_observations
                     WHERE observed_at_ms > ?1",
                    params![after_ms],
                    |row| row.get::<_, Option<i64>>(0),
                )?
                .unwrap_or(first_ms),
        };
        let start_ms = first_ms.div_euclid(MODEL_ROLLUP_HOUR_MS) * MODEL_ROLLUP_HOUR_MS;
        let end_ms = boundary_ms
            .div_euclid(MODEL_ROLLUP_HOUR_MS)
            .checked_add(1)
            .and_then(|hour| hour.checked_mul(MODEL_ROLLUP_HOUR_MS))
            .ok_or_else(|| model_backfill_sql_error("Model backfill hour boundary overflowed"))?;
        Ok(Some(PreparedModelBackfillRange { start_ms, end_ms }))
    }
}

impl RollupBackfillTarget for ModelRollupBackfillTarget {
    fn name(&self) -> &'static str {
        "model"
    }

    fn load_state(&self, conn: &Connection) -> rusqlite::Result<RollupBackfillState> {
        let (status, bookmark) = conn.query_row(
            "SELECT model_backfill_status, model_backfill_done_through_ms
             FROM rollup_meta WHERE id = 1",
            [],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<i64>>(1)?)),
        )?;
        let done_through = if status == "complete" {
            conn.query_row(
                "SELECT MAX(observed_at_ms) FROM model_usage_observations",
                [],
                |row| row.get::<_, Option<i64>>(0),
            )?
        } else {
            bookmark
        };
        let rows_done = match done_through {
            Some(done_through) => conn.query_row(
                "SELECT COUNT(*) FROM model_usage_observations
                 WHERE observed_at_ms <= ?1",
                params![done_through],
                |row| row.get::<_, u64>(0),
            )?,
            None => 0,
        };
        Ok(RollupBackfillState {
            rows_done,
            done_through,
        })
    }

    fn count_total_rows(&self, conn: &Connection) -> rusqlite::Result<u64> {
        conn.query_row("SELECT COUNT(*) FROM model_usage_observations", [], |row| {
            row.get(0)
        })
    }

    fn prepare_chunk(
        &mut self,
        conn: &Connection,
        state: RollupBackfillState,
        max_rows: u64,
    ) -> rusqlite::Result<()> {
        self.prepared = Self::prepare_range(conn, state.done_through.unwrap_or(-1), max_rows)?;
        Ok(())
    }

    fn fold_chunk(
        &mut self,
        tx: &rusqlite::Transaction<'_>,
        state: RollupBackfillState,
        budget: RollupBackfillChunkBudget,
    ) -> rusqlite::Result<RollupBackfillChunk> {
        self.chunk_changed = false;
        let reset_rows = if state.done_through.is_none() {
            tx.execute("DELETE FROM model_usage_hourly WHERE raw_pruned = 0", [])?
        } else {
            0
        };

        // Boundary selection happened before the ingest permit. Re-read the
        // current raw frontier inside this transaction so a replacement that
        // landed between preparation and admission is folded, never copied
        // from stale prepared data.
        let after_ms = state.done_through.unwrap_or(-1);
        let current_first = tx
            .query_row(
                "SELECT observed_at_ms
                 FROM model_usage_observations
                 WHERE observed_at_ms > ?1
                 ORDER BY observed_at_ms
                 LIMIT 1",
                params![after_ms],
                |row| row.get::<_, i64>(0),
            )
            .optional()?;
        let Some(current_first) = current_first else {
            self.chunk_changed = reset_rows > 0;
            return Ok(RollupBackfillChunk {
                rows_processed: 0,
                done_through: state.done_through,
                completed: true,
            });
        };
        let current_start = current_first.div_euclid(MODEL_ROLLUP_HOUR_MS) * MODEL_ROLLUP_HOUR_MS;
        let prepared_end = self
            .prepared
            .take()
            .filter(|range| range.start_ms <= current_first && current_first < range.end_ms)
            .map(|range| range.end_ms);
        let end_ms = match prepared_end {
            Some(end_ms) => end_ms,
            None => current_start
                .checked_add(MODEL_ROLLUP_HOUR_MS)
                .ok_or_else(|| {
                    model_backfill_sql_error("Model backfill hour boundary overflowed")
                })?,
        };

        let rows_processed = tx.query_row(
            "SELECT COUNT(*) FROM model_usage_observations
             WHERE observed_at_ms > ?1 AND observed_at_ms < ?2",
            params![after_ms, end_ms],
            |row| row.get::<_, u64>(0),
        )?;
        let deleted_rows = tx.execute(
            "DELETE FROM model_usage_hourly
             WHERE raw_pruned = 0 AND hour_utc >= ?1 AND hour_utc < ?2",
            params![current_start, end_ms],
        )?;
        let inserted_rows = tx.execute(
            "INSERT INTO model_usage_hourly (
                 hour_utc, provider, derived_model_id, source_key,
                 analytics_session_id, obs_count, turn_count, token_count,
                 sidechain_count, input_tokens, input_tokens_present,
                 output_tokens, output_tokens_present, cache_creation_tokens,
                 cache_creation_tokens_present, cache_read_tokens,
                 cache_read_tokens_present, first_observed_at_ms,
                 last_observed_at_ms, raw_pruned
             )
             SELECT (observed_at_ms / ?1) * ?1,
                    provider, COALESCE(derived_model_id, ''), source_key,
                    analytics_session_id, COUNT(*),
                    SUM(CASE WHEN observation_kind = 'turn' THEN 1 ELSE 0 END),
                    SUM(CASE WHEN observation_kind = 'token' THEN 1 ELSE 0 END),
                    SUM(is_sidechain), COALESCE(SUM(input_tokens), 0),
                    COUNT(input_tokens), COALESCE(SUM(output_tokens), 0),
                    COUNT(output_tokens), COALESCE(SUM(cache_creation_tokens), 0),
                    COUNT(cache_creation_tokens),
                    COALESCE(SUM(cache_read_tokens), 0), COUNT(cache_read_tokens),
                    MIN(observed_at_ms), MAX(observed_at_ms), 0
             FROM model_usage_observations
             WHERE observed_at_ms >= ?2 AND observed_at_ms < ?3
             GROUP BY (observed_at_ms / ?1) * ?1, provider,
                      COALESCE(derived_model_id, ''), source_key,
                      analytics_session_id
             ON CONFLICT(hour_utc, provider, derived_model_id, source_key)
             DO UPDATE SET
                 analytics_session_id = excluded.analytics_session_id,
                 obs_count = excluded.obs_count,
                 turn_count = excluded.turn_count,
                 token_count = excluded.token_count,
                 sidechain_count = excluded.sidechain_count,
                 input_tokens = excluded.input_tokens,
                 input_tokens_present = excluded.input_tokens_present,
                 output_tokens = excluded.output_tokens,
                 output_tokens_present = excluded.output_tokens_present,
                 cache_creation_tokens = excluded.cache_creation_tokens,
                 cache_creation_tokens_present = excluded.cache_creation_tokens_present,
                 cache_read_tokens = excluded.cache_read_tokens,
                 cache_read_tokens_present = excluded.cache_read_tokens_present,
                 first_observed_at_ms = excluded.first_observed_at_ms,
                 last_observed_at_ms = excluded.last_observed_at_ms
             WHERE model_usage_hourly.raw_pruned = 0",
            params![MODEL_ROLLUP_HOUR_MS, current_start, end_ms],
        )?;
        self.chunk_changed = reset_rows > 0 || deleted_rows > 0 || inserted_rows > 0;

        let completed = !tx.query_row(
            "SELECT EXISTS(
                 SELECT 1 FROM model_usage_observations
                 WHERE observed_at_ms >= ?1
             )",
            params![end_ms],
            |row| row.get::<_, bool>(0),
        )?;
        let done_through = end_ms.checked_sub(1).ok_or_else(|| {
            model_backfill_sql_error("Model backfill inclusive bookmark underflowed")
        })?;
        if budget.should_yield() {
            log::warn!(
                "Model rollup backfill chunk through {done_through} exceeded the 250 ms target"
            );
        }
        Ok(RollupBackfillChunk {
            rows_processed,
            done_through: Some(done_through),
            completed,
        })
    }

    fn persist_chunk(
        &self,
        tx: &rusqlite::Transaction<'_>,
        state: RollupBackfillState,
        completed: bool,
    ) -> rusqlite::Result<()> {
        let desired_status = if completed { "complete" } else { "running" };
        let desired_bookmark = if completed { None } else { state.done_through };
        let (current_status, current_bookmark) = tx.query_row(
            "SELECT model_backfill_status, model_backfill_done_through_ms
             FROM rollup_meta WHERE id = 1",
            [],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<i64>>(1)?)),
        )?;
        let generation_changed = self.chunk_changed
            || current_status != desired_status
            || current_bookmark != desired_bookmark;
        let updated = tx.execute(
            "UPDATE rollup_meta
             SET model_backfill_status = ?1,
                 model_backfill_done_through_ms = ?2,
                 rollup_generation = rollup_generation + ?3
             WHERE id = 1",
            params![
                desired_status,
                desired_bookmark,
                i64::from(generation_changed)
            ],
        )?;
        if updated != 1 {
            return Err(model_backfill_sql_error(
                "Model rollup metadata singleton is missing",
            ));
        }
        Ok(())
    }
}

impl RuntimeRollupBackfillTarget {
    fn prepare_source_rollup(
        conn: &Connection,
        after_rowid: i64,
    ) -> rusqlite::Result<Option<PreparedRuntimeBackfillSource>> {
        let identity = conn
            .query_row(
                "WITH next_source AS (
                     SELECT provider, source_key
                     FROM session_events
                     WHERE source_key IS NOT NULL AND rowid > ?1
                     ORDER BY rowid
                     LIMIT 1
                 )
                 SELECT event.provider, event.source_key,
                        MIN(event.rowid), MAX(event.rowid), COUNT(*),
                        MIN(event.session_id), MAX(event.session_id),
                        MIN(event.chain_id), MAX(event.chain_id),
                        source.content_sha256, source.seen_generation
                 FROM next_source AS next
                 JOIN session_events AS event
                   ON event.provider = next.provider
                  AND event.source_key = next.source_key
                 JOIN transcript_analytics_sources AS source
                   ON source.provider = event.provider
                  AND source.source_key = event.source_key
                 GROUP BY event.provider, event.source_key
                ",
                params![after_rowid],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, String>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, i64>(3)?,
                        row.get::<_, u64>(4)?,
                        row.get::<_, String>(5)?,
                        row.get::<_, String>(6)?,
                        row.get::<_, String>(7)?,
                        row.get::<_, String>(8)?,
                        row.get::<_, Option<String>>(9)?,
                        row.get::<_, i64>(10)?,
                    ))
                },
            )
            .optional()?;
        let Some((
            provider,
            source_key,
            first_rowid,
            last_rowid,
            row_count,
            first_session_id,
            last_session_id,
            first_chain_id,
            last_chain_id,
            content_sha256,
            seen_generation,
        )) = identity
        else {
            return Ok(None);
        };
        if first_session_id != last_session_id || first_chain_id != last_chain_id {
            return Err(runtime_backfill_sql_error(format!(
                "Runtime source {provider}/{source_key} has mixed session or chain identity"
            )));
        }
        let block_width = last_rowid
            .checked_sub(first_rowid)
            .and_then(|width| width.checked_add(1))
            .and_then(|width| u64::try_from(width).ok());
        if block_width != Some(row_count) {
            return Err(runtime_backfill_sql_error(format!(
                "Runtime source {provider}/{source_key} is not one contiguous rowid block"
            )));
        }

        let mut statement = conn.prepare(
            "SELECT rowid, timestamp, kind, session_id, chain_id
             FROM session_events
             WHERE provider = ?1 AND source_key = ?2
             ORDER BY timestamp, rowid",
        )?;
        let rows = statement.query_map(params![provider, source_key], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
                row.get::<_, String>(4)?,
            ))
        })?;
        let mut events = Vec::new();
        for row in rows {
            let (rowid, timestamp, kind, session_id, chain_id) = row?;
            if session_id != first_session_id || chain_id != first_chain_id {
                return Err(runtime_backfill_sql_error(format!(
                    "Runtime source {provider}/{source_key} changed identity during preparation"
                )));
            }
            let Ok(timestamp) = DateTime::parse_from_rfc3339(&timestamp) else {
                continue;
            };
            let timestamp_ms = timestamp.timestamp_millis();
            if timestamp_ms < 0 {
                return Err(runtime_backfill_sql_error(format!(
                    "Runtime event row {rowid} timestamp predates the Unix epoch"
                )));
            }
            events.push(PersistedRuntimeEvent {
                rowid,
                timestamp_ms,
                kind,
            });
        }

        let fold = fold_persisted_runtime_events(&events, "Runtime backfill")
            .map_err(runtime_backfill_sql_error)?;

        Ok(Some(PreparedRuntimeBackfillSource {
            provider,
            source_key,
            session_id: first_session_id,
            chain_id: first_chain_id,
            first_rowid,
            last_rowid,
            row_count,
            content_sha256,
            seen_generation,
            rollups: fold.rollups,
            finalized_through_rowid: fold.finalized_through_rowid,
            open_turn_started_ms: fold.open_turn_started_ms,
        }))
    }
}

impl RollupBackfillTarget for RuntimeRollupBackfillTarget {
    fn name(&self) -> &'static str {
        "runtime"
    }

    fn load_state(&self, conn: &Connection) -> rusqlite::Result<RollupBackfillState> {
        let (status, bookmark) = conn.query_row(
            "SELECT runtime_backfill_status, runtime_backfill_done_through_rowid
             FROM rollup_meta WHERE id = 1",
            [],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<i64>>(1)?)),
        )?;
        let done_through = if status == "complete" {
            conn.query_row(
                "SELECT MAX(rowid) FROM session_events WHERE source_key IS NOT NULL",
                [],
                |row| row.get::<_, Option<i64>>(0),
            )?
        } else {
            bookmark
        };
        let rows_done = match done_through {
            Some(rowid) => conn.query_row(
                "SELECT COUNT(*) FROM session_events
                 WHERE source_key IS NOT NULL AND rowid <= ?1",
                params![rowid],
                |row| row.get::<_, u64>(0),
            )?,
            None => 0,
        };
        Ok(RollupBackfillState {
            rows_done,
            done_through,
        })
    }

    fn count_total_rows(&self, conn: &Connection) -> rusqlite::Result<u64> {
        conn.query_row(
            "SELECT COUNT(*) FROM session_events WHERE source_key IS NOT NULL",
            [],
            |row| row.get(0),
        )
    }

    fn prepare_chunk(
        &mut self,
        conn: &Connection,
        state: RollupBackfillState,
        _max_rows: u64,
    ) -> rusqlite::Result<()> {
        self.prepared = Self::prepare_source_rollup(conn, state.done_through.unwrap_or(0))?;
        Ok(())
    }

    fn fold_chunk(
        &mut self,
        tx: &rusqlite::Transaction<'_>,
        state: RollupBackfillState,
        budget: RollupBackfillChunkBudget,
    ) -> rusqlite::Result<RollupBackfillChunk> {
        let reset_changed = if state.done_through.is_none() {
            let deleted_rollups =
                tx.execute("DELETE FROM runtime_hourly WHERE raw_pruned = 0", [])?;
            let deleted_states = tx.execute("DELETE FROM runtime_turn_state", [])?;
            deleted_rollups > 0 || deleted_states > 0
        } else {
            false
        };
        let Some(prepared) = self.prepared.take() else {
            if reset_changed {
                tx.execute(
                    "UPDATE rollup_meta
                     SET rollup_generation = rollup_generation + 1
                     WHERE id = 1",
                    [],
                )?;
            }
            return Ok(RollupBackfillChunk {
                rows_processed: 0,
                done_through: state.done_through,
                completed: true,
            });
        };

        let current = tx.query_row(
            "SELECT MIN(event.rowid), MAX(event.rowid), COUNT(*),
                    MIN(event.session_id), MAX(event.session_id),
                    MIN(event.chain_id), MAX(event.chain_id),
                    source.content_sha256, source.seen_generation
             FROM session_events AS event
             JOIN transcript_analytics_sources AS source
               ON source.provider = event.provider
              AND source.source_key = event.source_key
             WHERE event.provider = ?1 AND event.source_key = ?2",
            params![prepared.provider, prepared.source_key],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, u64>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(4)?,
                    row.get::<_, String>(5)?,
                    row.get::<_, String>(6)?,
                    row.get::<_, Option<String>>(7)?,
                    row.get::<_, i64>(8)?,
                ))
            },
        )?;
        let fingerprint_matches = current.0 == prepared.first_rowid
            && current.1 == prepared.last_rowid
            && current.2 == prepared.row_count
            && current.3 == prepared.session_id
            && current.4 == prepared.session_id
            && current.5 == prepared.chain_id
            && current.6 == prepared.chain_id
            && current.7 == prepared.content_sha256
            && current.8 == prepared.seen_generation;
        if !fingerprint_matches {
            return Err(runtime_backfill_sql_error(format!(
                "Runtime source {}/{} changed after preparation",
                prepared.provider, prepared.source_key
            )));
        }

        tx.execute(
            "DELETE FROM runtime_hourly
             WHERE provider = ?1 AND source_key = ?2 AND raw_pruned = 0",
            params![prepared.provider, prepared.source_key],
        )?;
        tx.execute(
            "DELETE FROM runtime_turn_state
             WHERE provider = ?1 AND source_key = ?2",
            params![prepared.provider, prepared.source_key],
        )?;
        for rollup in &prepared.rollups {
            tx.execute(
                "INSERT INTO runtime_hourly (
                     hour_utc, provider, source_key, session_id, turn_count,
                     runtime_secs, first_turn_start_ms, last_turn_end_ms,
                     raw_pruned
                 ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, 0)
                 ON CONFLICT(hour_utc, provider, source_key) DO UPDATE SET
                     session_id = excluded.session_id,
                     turn_count = excluded.turn_count,
                     runtime_secs = excluded.runtime_secs,
                     first_turn_start_ms = excluded.first_turn_start_ms,
                     last_turn_end_ms = excluded.last_turn_end_ms
                 WHERE runtime_hourly.raw_pruned = 0",
                params![
                    rollup.hour_utc,
                    prepared.provider,
                    prepared.source_key,
                    prepared.session_id,
                    rollup.turn_count,
                    rollup.runtime_millis as f64 / 1_000.0,
                    rollup.first_turn_start_ms,
                    rollup.last_turn_end_ms,
                ],
            )?;
            if budget.should_yield() {
                return Err(runtime_backfill_sql_error(format!(
                    "Runtime source {}/{} compact commit exceeded 250 ms",
                    prepared.provider, prepared.source_key
                )));
            }
        }
        if let Some(open_turn_started_ms) = prepared.open_turn_started_ms {
            tx.execute(
                "INSERT INTO runtime_turn_state (
                     provider, source_key, finalized_through_rowid,
                     open_turn_started_ms
                 ) VALUES (?1, ?2, ?3, ?4)",
                params![
                    prepared.provider,
                    prepared.source_key,
                    prepared.finalized_through_rowid,
                    open_turn_started_ms,
                ],
            )?;
        }
        let updated = tx.execute(
            "UPDATE rollup_meta
             SET rollup_generation = rollup_generation + 1
             WHERE id = 1",
            [],
        )?;
        if updated != 1 {
            return Err(runtime_backfill_sql_error(
                "Runtime rollup metadata singleton is missing",
            ));
        }
        if budget.should_yield() {
            return Err(runtime_backfill_sql_error(format!(
                "Runtime source {}/{} compact commit exceeded 250 ms",
                prepared.provider, prepared.source_key
            )));
        }
        let completed = !tx.query_row(
            "SELECT EXISTS(
                 SELECT 1 FROM session_events
                 WHERE source_key IS NOT NULL AND rowid > ?1
             )",
            params![prepared.last_rowid],
            |row| row.get::<_, bool>(0),
        )?;
        Ok(RollupBackfillChunk {
            rows_processed: prepared.row_count,
            done_through: Some(prepared.last_rowid),
            completed,
        })
    }

    fn persist_chunk(
        &self,
        tx: &rusqlite::Transaction<'_>,
        state: RollupBackfillState,
        completed: bool,
    ) -> rusqlite::Result<()> {
        let updated = tx.execute(
            "UPDATE rollup_meta
             SET runtime_backfill_status = ?1,
                 runtime_backfill_done_through_rowid = ?2
             WHERE id = 1",
            params![
                if completed { "complete" } else { "running" },
                if completed { None } else { state.done_through },
            ],
        )?;
        if updated != 1 {
            return Err(runtime_backfill_sql_error(
                "Runtime rollup metadata singleton is missing",
            ));
        }
        Ok(())
    }
}

struct RuntimeRollupStatsRow {
    hour_utc: i64,
    provider: String,
    session_id: String,
    turn_count: i64,
    runtime_secs: f64,
}

struct RuntimeOpenTailStatsRow {
    turn_start_ms: i64,
    provider: String,
    session_id: String,
    packed_last_event: Option<String>,
}

struct CompletedRuntimeRollupRows {
    rollups: Vec<RuntimeRollupStatsRow>,
    open_tails: Vec<RuntimeOpenTailStatsRow>,
}

fn read_completed_runtime_rollup_rows(
    conn: &Connection,
    window_start_ms: i64,
    parent_only: bool,
) -> Result<Option<CompletedRuntimeRollupRows>, String> {
    let complete = conn
        .query_row(
            "SELECT runtime_backfill_status = 'complete'
             FROM rollup_meta WHERE id = 1",
            [],
            |row| row.get::<_, bool>(0),
        )
        .map_err(|error| format!("Read runtime backfill status: {error}"))?;
    if !complete {
        return Ok(None);
    }

    let rollup_sql = format!(
        "SELECT rollup.hour_utc, rollup.provider, rollup.session_id,
                rollup.turn_count, rollup.runtime_secs
         FROM runtime_hourly AS rollup
         JOIN transcript_analytics_sources AS source
           ON source.provider = rollup.provider
          AND source.source_key = rollup.source_key
         WHERE rollup.hour_utc >= ?1
           AND {ACTIVE_RUNTIME_SOURCE_PREDICATE}{}",
        if parent_only {
            " AND source.is_sidechain = 0"
        } else {
            ""
        }
    );
    let rollups = {
        let mut statement = conn
            .prepare(&rollup_sql)
            .map_err(|error| format!("Prepare runtime rollup query: {error}"))?;
        let rows = statement
            .query_map(params![window_start_ms], |row| {
                Ok(RuntimeRollupStatsRow {
                    hour_utc: row.get(0)?,
                    provider: row.get(1)?,
                    session_id: row.get(2)?,
                    turn_count: row.get(3)?,
                    runtime_secs: row.get(4)?,
                })
            })
            .map_err(|error| format!("Query runtime rollups: {error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("Read runtime rollup: {error}"))?
    };

    let tail_sql = format!(
        "SELECT state.open_turn_started_ms, source.provider,
                source.analytics_session_id,
                (
                    SELECT event.timestamp || char(31) || event.kind
                    FROM session_events AS event
                         INDEXED BY idx_se_provider_chain_timestamp
                    WHERE event.provider = source.provider
                      AND event.chain_id = source.chain_id
                      AND event.source_key = source.source_key
                      AND event.rowid > state.finalized_through_rowid
                    ORDER BY event.timestamp DESC, event.rowid DESC
                    LIMIT 1
                )
         FROM runtime_turn_state AS state
         JOIN transcript_analytics_sources AS source
           ON source.provider = state.provider
          AND source.source_key = state.source_key
         WHERE state.open_turn_started_ms >= ?1
           AND {ACTIVE_RUNTIME_SOURCE_PREDICATE}{}",
        if parent_only {
            " AND source.is_sidechain = 0"
        } else {
            ""
        }
    );
    let open_tails = {
        let mut statement = conn
            .prepare(&tail_sql)
            .map_err(|error| format!("Prepare runtime open-tail query: {error}"))?;
        let rows = statement
            .query_map(params![window_start_ms], |row| {
                Ok(RuntimeOpenTailStatsRow {
                    turn_start_ms: row.get(0)?,
                    provider: row.get(1)?,
                    session_id: row.get(2)?,
                    packed_last_event: row.get(3)?,
                })
            })
            .map_err(|error| format!("Query runtime open tail: {error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("Read runtime open-tail row: {error}"))?
    };

    Ok(Some(CompletedRuntimeRollupRows {
        rollups,
        open_tails,
    }))
}

fn shape_completed_runtime_rollup_stats(
    rows: CompletedRuntimeRollupRows,
    from: DateTime<Utc>,
    now: DateTime<Utc>,
) -> Result<LlmRuntimeStats, String> {
    let range_secs = (now - from).num_seconds() as f64;
    let bucket_secs = range_secs / 7.0;
    let from_epoch_ms = from.timestamp_millis() as f64;
    let mut total_runtime_secs = 0.0_f64;
    let mut turn_count = 0_i64;
    let mut sessions = HashSet::<(String, String)>::new();
    let mut bucket_sums = [0.0_f64; 7];

    for row in rows.rollups {
        total_runtime_secs += row.runtime_secs;
        turn_count = turn_count
            .checked_add(row.turn_count)
            .ok_or_else(|| "Runtime rollup turn count overflowed".to_string())?;
        sessions.insert((row.provider, row.session_id));
        let bucket =
            ((((row.hour_utc as f64 - from_epoch_ms) / 1_000.0) / bucket_secs).max(0.0)) as usize;
        bucket_sums[bucket.min(6)] += row.runtime_secs;
    }

    for row in rows.open_tails {
        let Some(packed_last_event) = row.packed_last_event else {
            continue;
        };
        let Some((timestamp, kind)) = packed_last_event.split_once('\u{1f}') else {
            return Err("Runtime open-tail row has an invalid packed event".to_string());
        };
        let timestamp = DateTime::parse_from_rfc3339(timestamp)
            .map_err(|error| format!("Parse runtime open-tail timestamp: {error}"))?;
        let last_event_ms = timestamp.timestamp_millis();
        let end_ms = if kind == "asst_tool_use" {
            now.timestamp_millis()
                .min(last_event_ms.saturating_add(RUNTIME_TOOL_WAIT_MAX_MS))
        } else {
            last_event_ms
        };
        let duration = end_ms.saturating_sub(row.turn_start_ms) as f64 / 1_000.0;
        sessions.insert((row.provider, row.session_id));
        if duration > 0.0 {
            total_runtime_secs += duration;
            turn_count += 1;
            let bucket = ((((row.turn_start_ms as f64 - from_epoch_ms) / 1_000.0) / bucket_secs)
                .max(0.0)) as usize;
            bucket_sums[bucket.min(6)] += duration;
        }
    }
    let avg_per_turn_secs = if turn_count > 0 {
        total_runtime_secs / turn_count as f64
    } else {
        0.0
    };
    Ok(LlmRuntimeStats {
        total_runtime_secs,
        turn_count,
        session_count: sessions.len() as i64,
        avg_per_turn_secs,
        sparkline: bucket_sums.to_vec(),
    })
}

/// Delete every stale source owned by one completed root and its children.
///
/// Migration 28 deliberately does not enable connection-wide foreign keys,
/// so source pruning must preserve child-first ordering explicitly.
/// Accepting an existing transaction keeps both deletes in the caller's
/// atomic pruning operation.
fn bump_rollup_generation_in_transaction(tx: &rusqlite::Transaction<'_>) -> Result<(), String> {
    let updated = tx
        .execute(
            "UPDATE rollup_meta
             SET rollup_generation = rollup_generation + 1
             WHERE id = 1",
            [],
        )
        .map_err(|error| format!("Bump hourly rollup generation: {error}"))?;
    if updated != 1 {
        return Err("Hourly rollup metadata singleton is missing".to_string());
    }
    Ok(())
}

fn delete_model_rollups_for_sources_in_transaction(
    tx: &rusqlite::Transaction<'_>,
    sources: &[(String, String)],
) -> Result<usize, String> {
    let mut deleted = 0_usize;
    let mut statement = tx
        .prepare_cached(
            "DELETE FROM model_usage_hourly
             WHERE provider = ?1 AND source_key = ?2",
        )
        .map_err(|error| format!("Prepare model rollup source delete: {error}"))?;
    for (provider, source_key) in sources {
        deleted = deleted.saturating_add(
            statement
                .execute(params![provider, source_key])
                .map_err(|error| format!("Delete model rollup source rows: {error}"))?,
        );
    }
    drop(statement);
    if deleted > 0 {
        bump_rollup_generation_in_transaction(tx)?;
    }
    Ok(deleted)
}

fn delete_runtime_rollups_for_sources_in_transaction(
    tx: &rusqlite::Transaction<'_>,
    sources: &[(String, String)],
) -> Result<usize, String> {
    let mut deleted = 0_usize;
    for table in ["runtime_hourly", "runtime_turn_state"] {
        let mut statement = tx
            .prepare_cached(&format!(
                "DELETE FROM {table} WHERE provider = ?1 AND source_key = ?2"
            ))
            .map_err(|error| format!("Prepare {table} source delete: {error}"))?;
        for (provider, source_key) in sources {
            deleted = deleted.saturating_add(
                statement
                    .execute(params![provider, source_key])
                    .map_err(|error| format!("Delete {table} source rows: {error}"))?,
            );
        }
    }
    if deleted > 0 {
        bump_rollup_generation_in_transaction(tx)?;
    }
    Ok(deleted)
}

fn delete_model_observation_sources_for_root_in_transaction(
    tx: &rusqlite::Transaction<'_>,
    provider: &str,
    source_root_key: &str,
    generation: i64,
) -> Result<usize, String> {
    let stale_sources = {
        let mut statement = tx
            .prepare(
                "SELECT provider, source_key
                 FROM model_observation_sources
                 WHERE provider = ?1
                   AND source_root_key = ?2
                   AND seen_generation < ?3
                 ORDER BY source_key",
            )
            .map_err(|error| format!("Prepare completed-root model source keys: {error}"))?;
        let rows = statement
            .query_map(params![provider, source_root_key, generation], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })
            .map_err(|error| format!("Query completed-root model source keys: {error}"))?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(|error| format!("Read completed-root model source keys: {error}"))?
    };
    delete_model_rollups_for_sources_in_transaction(tx, &stale_sources)?;
    tx.execute(
        "DELETE FROM model_usage_observations
         WHERE provider = ?1
           AND source_key IN (
               SELECT source_key
               FROM model_observation_sources
               WHERE provider = ?1
                 AND source_root_key = ?2
                 AND seen_generation < ?3
           )",
        params![provider, source_root_key, generation],
    )
    .map_err(|e| format!("Delete completed-root model observation children: {e}"))?;

    tx.execute(
        "DELETE FROM model_observation_sources
         WHERE provider = ?1
           AND source_root_key = ?2
           AND seen_generation < ?3",
        params![provider, source_root_key, generation],
    )
    .map_err(|e| format!("Delete completed-root model observation parents: {e}"))
}

