    // @lat: [[backend#Backend#Database#Schema#Model Analytics Test Specs#Model Source Nickname Persistence]]
    #[test]
    #[serial]
    fn model_source_nickname_persists_without_changing_source_identity() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");
        let storage = init_storage_in(&dir);
        let path = dir.path().join("codex-source.jsonl");
        std::fs::write(&path, "").expect("write empty source");
        let fast = crate::transcript_identity::model_source_fast_fingerprint(
            &std::fs::metadata(&path).expect("stat empty source"),
        )
        .expect("fingerprint empty source");
        let fingerprint = ModelSourceFingerprint::from_content(fast, b"");
        let now_ms = Utc::now().timestamp_millis();
        let mut source = NormalizedSource {
            provider: IntegrationProvider::Codex,
            source_root_key: "root-codex".to_owned(),
            source_key: "source-codex".to_owned(),
            path,
            layout_hint: crate::sessions::RetainedJsonlSourceLayoutHint::CodexTranscript,
            source_session_id: Some("child-1".to_owned()),
            analytics_session_id: Some("parent-1".to_owned()),
            chain_id: Some("child-1".to_owned()),
            parent_chain_id: Some("parent-1".to_owned()),
            is_sidechain: true,
            agent_id: Some("child-1".to_owned()),
            agent_nickname: Some("worker-a".to_owned()),
            cwd: None,
            hostname: Some("host-a".to_owned()),
            first_activity_at_ms: None,
            last_activity_at_ms: None,
            mtime_ns: None,
            size_bytes: None,
            content_sha256: None,
            last_error: None,
            suppressed_sha256: None,
            suppressed_at_ms: None,
            seen_generation: 1,
            processing_status: SourceProcessingStatus::Ok,
            observation_count: 0,
            last_attempt_at_ms: Some(now_ms),
            last_success_at_ms: Some(now_ms),
        };
        storage
            .replace_model_source(&source, &[], &fingerprint)
            .expect("persist nickname");
        source.agent_nickname = Some("worker-b".to_owned());
        storage
            .replace_model_source(&source, &[], &fingerprint)
            .expect("update display nickname");

        let sources = storage
            .list_model_sources_for_root(IntegrationProvider::Codex, "root-codex")
            .expect("read model sources");
        assert_eq!(sources.len(), 1, "nickname must not alter the source key");
        assert_eq!(
            sources[0].last_good.agent_nickname.as_deref(),
            Some("worker-b")
        );
        clear_env();
    }

    #[derive(Debug, PartialEq, Eq)]
    struct ModelHourlyRollupRow {
        hour_utc: i64,
        provider: String,
        derived_model_id: String,
        source_key: String,
        analytics_session_id: String,
        obs_count: i64,
        turn_count: i64,
        token_count: i64,
        sidechain_count: i64,
        input_tokens: i64,
        input_tokens_present: i64,
        output_tokens: i64,
        output_tokens_present: i64,
        cache_creation_tokens: i64,
        cache_creation_tokens_present: i64,
        cache_read_tokens: i64,
        cache_read_tokens_present: i64,
        first_observed_at_ms: i64,
        last_observed_at_ms: i64,
        raw_pruned: i64,
    }

    fn read_model_hourly_rollup_rows(conn: &Connection, query: &str) -> Vec<ModelHourlyRollupRow> {
        let mut stmt = conn.prepare(query).expect("prepare rollup query");
        stmt.query_map([], |row| {
            Ok(ModelHourlyRollupRow {
                hour_utc: row.get(0)?,
                provider: row.get(1)?,
                derived_model_id: row.get(2)?,
                source_key: row.get(3)?,
                analytics_session_id: row.get(4)?,
                obs_count: row.get(5)?,
                turn_count: row.get(6)?,
                token_count: row.get(7)?,
                sidechain_count: row.get(8)?,
                input_tokens: row.get(9)?,
                input_tokens_present: row.get(10)?,
                output_tokens: row.get(11)?,
                output_tokens_present: row.get(12)?,
                cache_creation_tokens: row.get(13)?,
                cache_creation_tokens_present: row.get(14)?,
                cache_read_tokens: row.get(15)?,
                cache_read_tokens_present: row.get(16)?,
                first_observed_at_ms: row.get(17)?,
                last_observed_at_ms: row.get(18)?,
                raw_pruned: row.get(19)?,
            })
        })
        .expect("query rollup rows")
        .collect::<Result<Vec<_>, _>>()
        .expect("read rollup rows")
    }

    fn raw_model_hourly_rows(storage: &Storage) -> Vec<ModelHourlyRollupRow> {
        let conn = storage.conn.lock().unwrap();
        read_model_hourly_rollup_rows(
            &conn,
            "SELECT (observed_at_ms / 3600000) * 3600000,
                    provider, COALESCE(derived_model_id, ''), source_key,
                    analytics_session_id, COUNT(*),
                    SUM(observation_kind = 'turn'),
                    SUM(observation_kind = 'token'), SUM(is_sidechain),
                    SUM(COALESCE(input_tokens, 0)), COUNT(input_tokens),
                    SUM(COALESCE(output_tokens, 0)), COUNT(output_tokens),
                    SUM(COALESCE(cache_creation_tokens, 0)),
                    COUNT(cache_creation_tokens),
                    SUM(COALESCE(cache_read_tokens, 0)), COUNT(cache_read_tokens),
                    MIN(observed_at_ms), MAX(observed_at_ms), 0
             FROM model_usage_observations
             GROUP BY 1, 2, 3, 4, 5
             ORDER BY 1, 2, 3, 4, 5",
        )
    }

    fn unpruned_model_hourly_rows(storage: &Storage) -> Vec<ModelHourlyRollupRow> {
        let conn = storage.conn.lock().unwrap();
        read_model_hourly_rollup_rows(
            &conn,
            "SELECT hour_utc, provider, derived_model_id, source_key,
                    analytics_session_id, obs_count, turn_count, token_count,
                    sidechain_count, input_tokens, input_tokens_present,
                    output_tokens, output_tokens_present,
                    cache_creation_tokens, cache_creation_tokens_present,
                    cache_read_tokens, cache_read_tokens_present,
                    first_observed_at_ms, last_observed_at_ms, raw_pruned
             FROM model_usage_hourly
             WHERE raw_pruned = 0
             ORDER BY 1, 2, 3, 4, 5",
        )
    }

    // @lat: [[backend#Backend#Database#Schema#Model Analytics Test Specs#Model Hourly Ingest Fold Exactness]]
    #[test]
    #[serial]
    fn model_hourly_ingest_fold_matches_raw_and_rolls_back_atomically() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");
        let storage = init_storage_in(&dir);
        let source_key = "rollup-source";
        let jsonl = [
            r#"{"type":"assistant","timestamp":"2026-07-30T10:01:00Z","sessionId":"rollup-session","message":{"usage":{"output_tokens":0}}}"#.to_string(),
            r#"{"type":"assistant","timestamp":"2026-07-30T10:02:00Z","sessionId":"rollup-session","message":{"model":" ","usage":{"input_tokens":0}}}"#.to_string(),
            r#"{"type":"assistant","timestamp":"2026-07-30T10:10:00Z","sessionId":"rollup-session","message":{"model":"model-a","usage":{"input_tokens":0,"output_tokens":5,"cache_creation_input_tokens":0}}}"#.to_string(),
            r#"{"type":"assistant","timestamp":"2026-07-30T10:20:00Z","sessionId":"rollup-session","message":{"usage":{"input_tokens":3,"cache_read_input_tokens":0}}}"#.to_string(),
            r#"{"type":"assistant","timestamp":"2026-07-30T11:01:00Z","sessionId":"rollup-session","message":{"model":"model-b","usage":{"output_tokens":7}}}"#.to_string(),
        ]
        .join("\n");
        let (source, observations, fingerprint) =
            prepare_claude_model_source(&dir, source_key, "rollup-session", &jsonl);

        storage
            .replace_model_source(&source, &observations, &fingerprint)
            .expect("fold seeded source");

        const RAW_GROUP_BY: &str = "SELECT (observed_at_ms / 3600000) * 3600000,
                    provider, COALESCE(derived_model_id, ''), source_key,
                    MIN(analytics_session_id), COUNT(*),
                    SUM(observation_kind = 'turn'),
                    SUM(observation_kind = 'token'), SUM(is_sidechain),
                    SUM(COALESCE(input_tokens, 0)), COUNT(input_tokens),
                    SUM(COALESCE(output_tokens, 0)), COUNT(output_tokens),
                    SUM(COALESCE(cache_creation_tokens, 0)),
                    COUNT(cache_creation_tokens),
                    SUM(COALESCE(cache_read_tokens, 0)),
                    COUNT(cache_read_tokens), MIN(observed_at_ms),
                    MAX(observed_at_ms), 0
             FROM model_usage_observations
             WHERE provider = 'claude' AND source_key = 'rollup-source'
             GROUP BY 1, 2, 3, 4
             ORDER BY 1, 2, 3, 4";
        const FOLDED_ROWS: &str = "SELECT hour_utc, provider, derived_model_id, source_key,
                    analytics_session_id, obs_count, turn_count, token_count,
                    sidechain_count, input_tokens, input_tokens_present,
                    output_tokens, output_tokens_present,
                    cache_creation_tokens, cache_creation_tokens_present,
                    cache_read_tokens, cache_read_tokens_present,
                    first_observed_at_ms, last_observed_at_ms, raw_pruned
             FROM model_usage_hourly
             WHERE provider = 'claude' AND source_key = 'rollup-source'
             ORDER BY 1, 2, 3, 4";
        {
            let conn = storage.conn.lock().unwrap();
            let raw = read_model_hourly_rollup_rows(&conn, RAW_GROUP_BY);
            let folded = read_model_hourly_rollup_rows(&conn, FOLDED_ROWS);
            assert_eq!(folded, raw, "ingest fold must equal raw source group-by");
            let unattributed = folded
                .iter()
                .find(|row| row.derived_model_id.is_empty())
                .expect("unattributed rollup bucket");
            assert_eq!((unattributed.obs_count, unattributed.turn_count), (2, 2));
            assert_eq!(
                (unattributed.input_tokens, unattributed.input_tokens_present),
                (0, 1)
            );
            assert_eq!(
                (
                    unattributed.output_tokens,
                    unattributed.output_tokens_present
                ),
                (0, 1)
            );
            assert_eq!(
                conn.query_row(
                    "SELECT rollup_generation FROM rollup_meta WHERE id = 1",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("read generation"),
                1
            );
        }

        storage
            .replace_model_source(&source, &observations, &fingerprint)
            .expect("replace seeded source");
        {
            let conn = storage.conn.lock().unwrap();
            assert_eq!(
                read_model_hourly_rollup_rows(&conn, FOLDED_ROWS),
                read_model_hourly_rollup_rows(&conn, RAW_GROUP_BY),
                "replacement must refold rather than accumulate duplicate counts"
            );
            assert_eq!(
                conn.query_row(
                    "SELECT rollup_generation FROM rollup_meta WHERE id = 1",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("read replacement generation"),
                2,
                "generation increments once per replacement transaction"
            );
            conn.execute_batch(
                "CREATE TRIGGER fail_rollup_source_metadata
                 BEFORE INSERT ON model_observation_sources
                 WHEN NEW.source_key = 'rollback-source'
                 BEGIN
                     SELECT RAISE(ABORT, 'forced source metadata failure');
                 END;",
            )
            .expect("install rollback trigger");
        }

        let rollback_jsonl = r#"{"type":"assistant","timestamp":"2026-07-30T12:00:00Z","sessionId":"rollback-session","message":{"model":"model-c","usage":{"input_tokens":9}}}"#;
        let (rollback_source, rollback_observations, rollback_fingerprint) =
            prepare_claude_model_source(
                &dir,
                "rollback-source",
                "rollback-session",
                rollback_jsonl,
            );
        assert!(
            storage
                .replace_model_source(
                    &rollback_source,
                    &rollback_observations,
                    &rollback_fingerprint,
                )
                .is_err(),
            "forced metadata failure must abort replacement"
        );
        {
            let conn = storage.conn.lock().unwrap();
            assert_eq!(
                conn.query_row(
                    "SELECT COUNT(*) FROM model_usage_observations
                     WHERE source_key = 'rollback-source'",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("count rolled-back raw rows"),
                0
            );
            assert_eq!(
                conn.query_row(
                    "SELECT COUNT(*) FROM model_usage_hourly
                     WHERE source_key = 'rollback-source'",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("count rolled-back rollup rows"),
                0
            );
            assert_eq!(
                conn.query_row(
                    "SELECT rollup_generation FROM rollup_meta WHERE id = 1",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("read rolled-back generation"),
                2
            );
            conn.execute_batch(
                "PRAGMA ignore_check_constraints = ON;
                 CREATE TRIGGER overflow_model_hourly_sum
                 AFTER INSERT ON model_usage_observations
                 WHEN NEW.source_key = 'overflow-source'
                 BEGIN
                     UPDATE model_usage_observations
                     SET input_tokens = 9223372036854775807
                     WHERE rowid = NEW.rowid;
                 END;",
            )
            .expect("install rollup overflow trigger");
        }

        let overflow_jsonl = [
            r#"{"type":"assistant","timestamp":"2026-07-30T13:00:00Z","sessionId":"overflow-session","message":{"model":"model-d","usage":{"input_tokens":1}}}"#,
            r#"{"type":"assistant","timestamp":"2026-07-30T13:01:00Z","sessionId":"overflow-session","message":{"model":"model-d","usage":{"input_tokens":1}}}"#,
        ]
        .join("\n");
        let (overflow_source, overflow_observations, overflow_fingerprint) =
            prepare_claude_model_source(
                &dir,
                "overflow-source",
                "overflow-session",
                &overflow_jsonl,
            );
        let error = storage
            .replace_model_source(
                &overflow_source,
                &overflow_observations,
                &overflow_fingerprint,
            )
            .expect_err("integer overflow must abort replacement");
        assert!(error.contains("integer overflow"), "{error}");
        {
            let conn = storage.conn.lock().unwrap();
            conn.execute_batch("PRAGMA ignore_check_constraints = OFF;")
                .expect("restore check constraints");
            for table in [
                "model_usage_observations",
                "model_usage_hourly",
                "model_observation_sources",
            ] {
                assert_eq!(
                    conn.query_row(
                        &format!(
                            "SELECT COUNT(*) FROM {table} WHERE source_key = 'overflow-source'"
                        ),
                        [],
                        |row| row.get::<_, i64>(0)
                    )
                    .expect("count overflow rows"),
                    0,
                    "overflow must roll back {table}"
                );
            }
            assert_eq!(
                conn.query_row(
                    "SELECT rollup_generation FROM rollup_meta WHERE id = 1",
                    [],
                    |row| row.get::<_, i64>(0)
                )
                .expect("read generation after overflow"),
                2
            );
        }
        clear_env();
    }

    fn percentile_95_ms(samples: &mut [Duration]) -> f64 {
        samples.sort_unstable();
        let index = (samples.len() * 95).div_ceil(100).saturating_sub(1);
        samples[index].as_secs_f64() * 1_000.0
    }

    /// Diagnostic acceptance benchmark. Run in release mode with ignored
    /// tests enabled so optimizer and SQLite behavior match production.
    // @lat: [[backend#Backend#Database#Schema#Model Analytics Test Specs#Model Hourly Ingest Fold Burst Budget]]
    #[test]
    #[ignore = "burst-shaped ingest timing acceptance"]
    #[serial]
    fn model_hourly_ingest_fold_burst_p95_stays_within_budget() {
        clear_env();
        const BURST_ROWS: usize = 6_000;
        const SAMPLES: usize = 25;
        let mut lines = Vec::with_capacity(BURST_ROWS);
        for ordinal in 0..BURST_ROWS {
            let second = ordinal % 60;
            let minute = (ordinal / 60) % 10;
            let model = if ordinal % 2 == 0 {
                "model-a"
            } else {
                "model-b"
            };
            lines.push(format!(
                r#"{{"type":"assistant","timestamp":"2026-07-30T10:{minute:02}:{second:02}Z","sessionId":"burst-session","message":{{"model":"{model}","usage":{{"input_tokens":2,"output_tokens":1,"cache_read_input_tokens":0}}}}}}"#
            ));
        }
        let jsonl = lines.join("\n");
        let control_dir = TempDir::new().expect("control tempdir");
        let control = init_storage_in(&control_dir);
        let (control_source, control_observations, control_fingerprint) =
            prepare_claude_model_source(&control_dir, "burst-source", "burst-session", &jsonl);
        let fold_dir = TempDir::new().expect("fold tempdir");
        let fold = init_storage_in(&fold_dir);
        let (fold_source, fold_observations, fold_fingerprint) =
            prepare_claude_model_source(&fold_dir, "burst-source", "burst-session", &jsonl);

        control
            .replace_model_source_without_rollup_for_benchmark(
                &control_source,
                &control_observations,
                &control_fingerprint,
            )
            .expect("warm control replacement");
        fold.replace_model_source(&fold_source, &fold_observations, &fold_fingerprint)
            .expect("warm folded replacement");

        let mut control_samples = Vec::with_capacity(SAMPLES);
        let mut fold_samples = Vec::with_capacity(SAMPLES);
        for _ in 0..SAMPLES {
            let started = Instant::now();
            control
                .replace_model_source_without_rollup_for_benchmark(
                    &control_source,
                    &control_observations,
                    &control_fingerprint,
                )
                .expect("control replacement");
            control_samples.push(started.elapsed());

            let started = Instant::now();
            fold.replace_model_source(&fold_source, &fold_observations, &fold_fingerprint)
                .expect("folded replacement");
            fold_samples.push(started.elapsed());
        }

        let control_p95_ms = percentile_95_ms(&mut control_samples);
        let fold_p95_ms = percentile_95_ms(&mut fold_samples);
        let delta_percent = ((fold_p95_ms - control_p95_ms) / control_p95_ms) * 100.0;
        eprintln!("model_rollup_fold.burst_rows={BURST_ROWS}");
        eprintln!("model_rollup_fold.samples={SAMPLES}");
        eprintln!("model_rollup_fold.control_p95_ms={control_p95_ms:.3}");
        eprintln!("model_rollup_fold.fold_p95_ms={fold_p95_ms:.3}");
        eprintln!("model_rollup_fold.delta_percent={delta_percent:.3}");
        assert!(
            delta_percent <= 10.0,
            "fold p95 overhead {delta_percent:.3}% exceeds 10% budget"
        );
        clear_env();
    }

    /// Diagnostic acceptance benchmark. Run in release mode so source
    /// replacement, timestamp parsing, sorting, and SQLite match production.
    // @lat: [[runtime-rollup-tests#Runtime Rollup Test Specs#Runtime Fold Burst Budget]]
    #[test]
    #[ignore = "burst-shaped runtime ingest timing acceptance"]
    #[serial]
    fn runtime_hourly_ingest_fold_burst_p95_stays_within_budget() {
        clear_env();
        const BURST_ROWS: usize = 6_000;
        const SAMPLES: usize = 25;
        let base = DateTime::parse_from_rfc3339("2026-07-30T10:00:00Z").expect("base time");
        let mut elapsed_ms = 0_i64;
        let mut events = Vec::with_capacity(BURST_ROWS);
        for ordinal in 0..BURST_ROWS {
            if ordinal > 0 {
                elapsed_ms += if ordinal % 250 == 0 { 360_000 } else { 1_000 };
            }
            let kind = match ordinal % 4 {
                0 => crate::sessions::SessionEventKind::UserText,
                1 => crate::sessions::SessionEventKind::AsstThinking,
                2 => crate::sessions::SessionEventKind::AsstToolUse,
                _ => crate::sessions::SessionEventKind::UserToolResult,
            };
            events.push((
                (base + chrono::Duration::milliseconds(elapsed_ms)).to_rfc3339(),
                kind,
            ));
        }
        let spec = TranscriptSourceSpec {
            provider: IntegrationProvider::Claude,
            source_root_key: "root-runtime-burst",
            source_key: "runtime-burst-source",
            session_id: "runtime-burst-session",
            generation: 1,
            marker: "runtime-burst",
            rows: 0,
        };
        let control_snapshot = runtime_snapshot(&spec, &events);
        let fold_snapshot = runtime_snapshot(&spec, &events);
        let control_dir = TempDir::new().expect("control tempdir");
        let control = init_storage_in(&control_dir);
        let fold_dir = TempDir::new().expect("fold tempdir");
        let fold = init_storage_in(&fold_dir);

        control
            .replace_transcript_analytics_snapshot_without_runtime_rollup_for_benchmark(
                &control_snapshot,
            )
            .expect("warm control replacement");
        fold.replace_transcript_analytics_snapshot(&fold_snapshot)
            .expect("warm folded replacement");

        let mut control_samples = Vec::with_capacity(SAMPLES);
        let mut fold_samples = Vec::with_capacity(SAMPLES);
        for _ in 0..SAMPLES {
            let started = Instant::now();
            control
                .replace_transcript_analytics_snapshot_without_runtime_rollup_for_benchmark(
                    &control_snapshot,
                )
                .expect("control replacement");
            control_samples.push(started.elapsed());

            let started = Instant::now();
            fold.replace_transcript_analytics_snapshot(&fold_snapshot)
                .expect("folded replacement");
            fold_samples.push(started.elapsed());
        }

        let control_p95_ms = percentile_95_ms(&mut control_samples);
        let fold_p95_ms = percentile_95_ms(&mut fold_samples);
        let delta_percent = ((fold_p95_ms - control_p95_ms) / control_p95_ms) * 100.0;
        eprintln!("runtime_rollup_fold.burst_rows={BURST_ROWS}");
        eprintln!("runtime_rollup_fold.samples={SAMPLES}");
        eprintln!("runtime_rollup_fold.control_p95_ms={control_p95_ms:.3}");
        eprintln!("runtime_rollup_fold.fold_p95_ms={fold_p95_ms:.3}");
        eprintln!("runtime_rollup_fold.delta_percent={delta_percent:.3}");
        assert!(
            delta_percent <= 10.0,
            "runtime fold p95 overhead {delta_percent:.3}% exceeds 10% budget"
        );
        clear_env();
    }

    // @lat: [[backend#Backend#Database#Schema#Model Analytics Test Specs#Model Sessions Cursor Codec]]
    #[test]
    fn model_sessions_cursor_round_trips_and_rejects_tampering() {
        let identity = ModelIdentity {
            provider: "claude".to_string(),
            model_id: "claude-opus-4".to_string(),
        };
        let range_end_ms = 2_000_000_000_000_i64;
        let range_start_ms =
            range_end_ms - model_range_duration(ModelRange::OneHour).num_milliseconds();
        let cursor = ModelSessionsCursorV1 {
            range: ModelRange::OneHour.as_str().to_string(),
            model_provider: "claude".to_string(),
            model_id: "claude-opus-4".to_string(),
            data_revision: 7,
            range_start_ms,
            range_end_ms,
            last_activity_ms: range_start_ms + 1_000,
            provider: "claude".to_string(),
            session_id: "sess-1".to_string(),
        };

        let encoded = encode_model_sessions_cursor(&cursor).expect("encode cursor");
        let decoded = decode_model_sessions_cursor(&encoded, ModelRange::OneHour, &identity)
            .expect("decode cursor");
        assert_eq!(decoded.range, cursor.range);
        assert_eq!(decoded.model_provider, cursor.model_provider);
        assert_eq!(decoded.model_id, cursor.model_id);
        assert_eq!(decoded.data_revision, cursor.data_revision);
        assert_eq!(decoded.range_start_ms, cursor.range_start_ms);
        assert_eq!(decoded.range_end_ms, cursor.range_end_ms);
        assert_eq!(decoded.last_activity_ms, cursor.last_activity_ms);
        assert_eq!(decoded.provider, cursor.provider);
        assert_eq!(decoded.session_id, cursor.session_id);

        // Flip the final checksum nibble: the envelope stays well-formed but the
        // checksum no longer matches the payload.
        let mut flipped = encoded.clone();
        let last = flipped.pop().expect("non-empty cursor");
        flipped.push(if last == '0' { '1' } else { '0' });
        assert!(matches!(
            decode_model_sessions_cursor(&flipped, ModelRange::OneHour, &identity),
            Err(ModelSessionsQueryError::InvalidCursor(_))
        ));

        // Truncation corrupts the checksum length/value.
        let truncated = &encoded[..encoded.len() - 2];
        assert!(matches!(
            decode_model_sessions_cursor(truncated, ModelRange::OneHour, &identity),
            Err(ModelSessionsQueryError::InvalidCursor(_))
        ));
    }

    // @lat: [[backend#Backend#Database#Schema#Model Analytics Test Specs#Bounded Completed Model Raw Seeks]]
    #[test]
    #[serial]
    fn completed_model_residual_reads_use_bounded_index_seeks() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");
        let storage = init_storage_in(&dir);
        let conn = storage.conn.lock().unwrap();
        assert_eq!(rusqlite::version(), "3.45.0");

        conn.execute_batch(
            "CREATE TEMP TABLE scoped_overview (
                 provider TEXT NOT NULL,
                 analytics_session_id TEXT NOT NULL
             );
             CREATE INDEX temp.scoped_overview_provider_session
                 ON scoped_overview(provider, analytics_session_id);",
        )
        .expect("create scoped overview plan fixture");
        materialize_model_read_authority(&conn, 0, 1, true)
            .expect("materialize active plan sources");

        let mut project_prefix_explain = conn
            .prepare(&format!(
                "EXPLAIN QUERY PLAN {}",
                completed_model_project_prefix_sql()
            ))
            .expect("prepare project prefix explain");
        let project_prefix_details = project_prefix_explain
            .query_map(
                params![
                    "claude",
                    "session",
                    "chain",
                    0_i64,
                    1_i64,
                    Option::<i64>::None,
                    Option::<i64>::None,
                ],
                |row| row.get::<_, String>(3),
            )
            .expect("query project prefix explain")
            .collect::<Result<Vec<_>, _>>()
            .expect("collect project prefix explain");
        assert!(
            project_prefix_details.iter().any(|detail| {
                detail.contains("SEARCH observation USING")
                    && detail.contains("idx_model_observations_chain_time")
                    && detail.contains("provider=? AND analytics_session_id=? AND chain_id=?")
                    && detail.contains("observed_at_ms>? AND observed_at_ms<?")
            }),
            "project prefix must seek each scoped chain's bounded raw range: {project_prefix_details:?}"
        );
        assert!(
            project_prefix_details
                .iter()
                .all(|detail| !detail.contains("SCAN observation")
                    && !detail.contains("TEMP B-TREE")),
            "project prefix must avoid raw scans and temporary ordering: {project_prefix_details:?}"
        );

        let mut project_ties_explain = conn
            .prepare(&format!(
                "EXPLAIN QUERY PLAN {}",
                completed_model_project_ties_sql()
            ))
            .expect("prepare project ties explain");
        let project_ties_details = project_ties_explain
            .query_map(params!["claude", "session", "chain", 0_i64, 0_i64], |row| {
                row.get::<_, String>(3)
            })
            .expect("query project ties explain")
            .collect::<Result<Vec<_>, _>>()
            .expect("collect project ties explain");
        assert!(
            project_ties_details.iter().any(|detail| {
                detail.contains("SEARCH observation USING")
                    && detail.contains("idx_model_observations_chain_time")
                    && detail.contains("provider=? AND analytics_session_id=? AND chain_id=?")
                    && detail.contains("observed_at_ms=? AND source_ordinal=?")
            }),
            "project ties must seek one exact chain prefix: {project_ties_details:?}"
        );
        assert!(
            project_ties_details
                .iter()
                .all(|detail| !detail.contains("SCAN observation")
                    && !detail.contains("TEMP B-TREE")),
            "project ties must avoid raw scans and temporary ordering: {project_ties_details:?}"
        );

        let running_sql = completed_model_running_turns_sql(false);
        let mut running_explain = conn
            .prepare(&format!("EXPLAIN QUERY PLAN {running_sql}"))
            .expect("prepare running turns explain");
        let running_details = running_explain
            .query_map(
                params![
                    0_i64,
                    1_i64,
                    Option::<String>::None,
                    Option::<i64>::None,
                    Option::<String>::None,
                    Option::<i64>::None,
                    1_024_i64,
                ],
                |row| row.get::<_, String>(3),
            )
            .expect("query running turns explain")
            .collect::<Result<Vec<_>, _>>()
            .expect("collect running turns explain");
        assert!(
            running_details.iter().any(|detail| {
                detail.contains("SEARCH observation USING")
                    && detail.contains("idx_model_observations_observed_provider")
                    && detail.contains("observed_at_ms>? AND observed_at_ms<?")
            }),
            "running turns must use a bounded observed-time seek: {running_details:?}"
        );
        assert!(
            running_details
                .iter()
                .all(|detail| !detail.contains("SCAN observation")
                    && !detail.contains("TEMP B-TREE")),
            "running turns must avoid raw scans and temporary ordering: {running_details:?}"
        );

        let raw_sql = model_raw_residual_branch_sql("observation.id", 1, 2, 3, true);
        let mut raw_explain = conn
            .prepare(&format!("EXPLAIN QUERY PLAN {raw_sql}"))
            .expect("prepare residual branch explain");
        let raw_details = raw_explain
            .query_map(params![0_i64, 1_i64, Option::<String>::None], |row| {
                row.get::<_, String>(3)
            })
            .expect("query residual branch explain")
            .collect::<Result<Vec<_>, _>>()
            .expect("collect residual branch explain");
        assert!(
            raw_details.iter().any(|detail| {
                detail.contains("SEARCH observation USING INDEX")
                    && detail.contains("idx_model_observations_observed_provider")
                    && detail.contains("observed_at_ms>? AND observed_at_ms<?")
            }),
            "residual branch must use a bounded observed-time seek: {raw_details:?}"
        );

        let range_end_ms = DateTime::parse_from_rfc3339("2026-08-02T19:27:43Z")
            .expect("pinned end")
            .timestamp_millis();
        for (days, expected_ranges) in [(30, 31), (90, 91)] {
            let range_start_ms = range_end_ms - TimeDelta::days(days).num_milliseconds();
            let (rollup_start_ms, rollup_end_ms) =
                model_rollup_closed_bounds(range_start_ms, range_end_ms);
            let ranges = model_rollup_residual_ranges(
                range_start_ms,
                range_end_ms,
                TimeDelta::days(1).num_milliseconds(),
                rollup_start_ms,
                rollup_end_ms,
            )
            .expect("daily residual ranges");
            assert_eq!(ranges.len(), expected_ranges);
            assert!(ranges.windows(2).all(|pair| pair[0].1 < pair[1].0));
            assert!(ranges.iter().all(|(start, end)| start < end));
        }
        clear_env();
    }

