    // @lat: [[backend#Backend#Database#Schema#Transcript Analytics Test Specs#Codex Identity Reingest Idempotence]]
    #[test]
    #[serial]
    fn codex_identity_reingest_is_complete_and_idempotent() {
        clear_env();
        let data_dir = TempDir::new().expect("data tempdir");
        let claude_dir = TempDir::new().expect("Claude tempdir");
        let codex_dir = TempDir::new().expect("Codex tempdir");
        let rollout_dir = codex_dir.path().join("2026/08/01");
        std::fs::create_dir_all(&rollout_dir).expect("create rollout dir");
        let rollout = rollout_dir.join("rollout-child-1.jsonl");
        let now = Utc::now();
        let pre_watermark =
            (now - TimeDelta::days(3)).to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
        let watermark =
            (now - TimeDelta::days(2)).to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
        let post_watermark =
            (now - TimeDelta::days(1)).to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
        let grown_at =
            (now - TimeDelta::hours(12)).to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
        let initial = [
            serde_json::json!({
                "type": "session_meta",
                "timestamp": pre_watermark,
                "payload": {
                    "id": "child-1",
                    "thread_source": "subagent",
                    "agent_nickname": "worker",
                    "source": { "subagent": { "thread_spawn": {
                        "parent_thread_id": "parent-1"
                    } } }
                }
            })
            .to_string(),
            serde_json::json!({
                "type": "turn_context",
                "timestamp": post_watermark,
                "payload": { "model": "gpt-5-codex", "turn_id": "turn-1" }
            })
            .to_string(),
            serde_json::json!({
                "type": "event_msg",
                "timestamp": post_watermark,
                "payload": { "type": "token_count", "info": {
                    "total_token_usage": {
                        "input_tokens": 100,
                        "cached_input_tokens": 0,
                        "output_tokens": 50,
                        "cache_creation_tokens": 0
                    }
                } }
            })
            .to_string(),
            serde_json::json!({
                "type": "event_msg",
                "timestamp": pre_watermark,
                "payload": {
                    "type": "agent_message", "id": "event-old", "message": "old"
                }
            })
            .to_string(),
            serde_json::json!({
                "type": "event_msg",
                "timestamp": post_watermark,
                "payload": {
                    "type": "agent_message", "id": "event-new", "message": "new"
                }
            })
            .to_string(),
        ]
        .join("\n")
            + "\n";
        std::fs::write(&rollout, &initial).expect("write Codex rollout");
        // SAFETY: environment mutation; this test is serialized.
        unsafe {
            std::env::set_var("QUILL_CLAUDE_PROJECTS_DIR", claude_dir.path());
            std::env::set_var("QUILL_CODEX_SESSIONS_DIR", codex_dir.path());
        }
        let storage = init_storage_in(&data_dir);
        storage
            .advance_retention_watermark(&watermark)
            .expect("seed retention watermark");
        let retained_day = &pre_watermark[..10];
        {
            let conn = storage.conn.lock().unwrap();
            conn.execute(
                "INSERT INTO retention_daily_aggregates
                     (provider, source_key, session_id, day,
                      session_event_count)
                 VALUES ('codex', 'codex-source', 'parent-1', ?1, 7)",
                params![retained_day],
            )
            .expect("seed pre-migration retention authority");
        }

        let persist_model_parse = |contents: &str, generation: i64| {
            let layout_hint = crate::sessions::RetainedJsonlSourceLayoutHint::CodexTranscript;
            let context = crate::model_usage::CodexAdapterContext {
                source_key: "codex-source",
                layout_hint: &layout_hint,
                hostname: Some("host-a"),
            };
            let mut parsed = crate::model_usage::parse_codex_model_usage_jsonl(contents, context);
            parsed
                .resolve_analytics_root("parent-1")
                .expect("Codex observations keep native identity while the file grows");
            let native = match &parsed.native_identity {
                crate::model_usage::ProviderNativeIdentityState::Valid(native) => native,
                state => panic!("expected valid Codex native identity, got {state:?}"),
            };
            let metadata = std::fs::metadata(&rollout).expect("stat Codex rollout");
            let fast = crate::transcript_identity::model_source_fast_fingerprint(&metadata)
                .expect("fingerprint Codex rollout");
            let fingerprint = ModelSourceFingerprint::from_content(fast, contents.as_bytes());
            let attempted_at_ms = Utc::now().timestamp_millis();
            let source = NormalizedSource {
                provider: IntegrationProvider::Codex,
                source_root_key: "codex-root".to_string(),
                source_key: "codex-source".to_string(),
                path: rollout.clone(),
                layout_hint,
                source_session_id: Some(native.source_session_id.clone()),
                analytics_session_id: Some(native.analytics_session_id().to_string()),
                chain_id: Some(native.chain_id.clone()),
                parent_chain_id: native.parent_chain_id.clone(),
                is_sidechain: native.is_sidechain,
                agent_id: native.agent_id.clone(),
                agent_nickname: native.agent_nickname.clone(),
                cwd: native.cwd.clone(),
                hostname: native.hostname.clone(),
                first_activity_at_ms: Some(native.first_activity_at_ms),
                last_activity_at_ms: Some(native.last_activity_at_ms),
                mtime_ns: None,
                size_bytes: None,
                content_sha256: None,
                last_error: None,
                suppressed_sha256: None,
                suppressed_at_ms: None,
                seen_generation: generation,
                processing_status: SourceProcessingStatus::Ok,
                observation_count: i64::try_from(parsed.observations.len())
                    .expect("model observation count"),
                last_attempt_at_ms: Some(attempted_at_ms),
                last_success_at_ms: Some(attempted_at_ms),
            };
            storage
                .replace_model_source(&source, &parsed.observations, &fingerprint)
                .expect("persist Codex model source");
        };
        persist_model_parse(&initial, 1);

        let reconcile = || {
            crate::transcript_analytics::run_startup_transcript_analytics_reconciliation(
                &storage, "host-a",
            )
            .expect("reconcile Codex rollout")
        };
        let first = reconcile();
        assert!(first.completed_all_roots);
        let analytics_counts = || {
            let conn = storage.conn.lock().unwrap();
            (
                scalar_count(
                    &conn,
                    "SELECT COUNT(*) FROM session_events
                     WHERE provider = 'codex' AND is_sidechain = 1",
                ),
                scalar_count(
                    &conn,
                    "SELECT COUNT(*) FROM session_events
                     WHERE provider = 'codex' AND is_sidechain = 1
                       AND agent_id IS NULL",
                ),
                scalar_count(
                    &conn,
                    "SELECT COUNT(*) FROM (
                         SELECT 1 FROM session_events
                         WHERE provider = 'codex' AND is_sidechain = 1
                         GROUP BY session_id, timestamp, kind
                         HAVING COUNT(*) > 1
                     )",
                ),
            )
        };
        assert_eq!(analytics_counts(), (1, 0, 0));

        let second = reconcile();
        assert!(second.completed_all_roots);
        assert_eq!(
            analytics_counts(),
            (1, 0, 0),
            "unchanged replay must not duplicate events"
        );

        let grown = initial
            + &serde_json::json!({
                "type": "event_msg",
                "timestamp": grown_at,
                "payload": { "type": "token_count", "info": {
                    "total_token_usage": {
                        "input_tokens": 150,
                        "cached_input_tokens": 0,
                        "output_tokens": 75,
                        "cache_creation_tokens": 0
                    }
                } }
            })
            .to_string()
            + "\n";
        std::fs::write(&rollout, &grown).expect("grow Codex rollout");
        persist_model_parse(&grown, 2);
        let third = reconcile();
        assert!(third.completed_all_roots);
        assert_eq!(
            analytics_counts(),
            (1, 0, 0),
            "changed replay must preserve event uniqueness and attribution"
        );

        let history = storage
            .get_session_model_history("codex", "parent-1", ModelRange::SevenDays)
            .expect("read Codex model history");
        let child = history
            .chains
            .iter()
            .find(|chain| chain.chain_id == "child-1")
            .expect("Codex child chain");
        assert!(matches!(child.kind, SessionModelChainKind::Subagent));
        assert_eq!(child.agent_id.as_deref(), Some("child-1"));

        let conn = storage.conn.lock().unwrap();
        assert_eq!(
            conn.query_row(
                "SELECT session_event_count
                 FROM retention_daily_aggregates
                 WHERE provider = 'codex' AND source_key = 'codex-source'
                   AND session_id = 'parent-1' AND day = ?1",
                params![retained_day],
                |row| row.get::<_, i64>(0),
            )
            .expect("read retained aggregate after replays"),
            7,
            "reingest must not add suppressed detail to retained authority"
        );
        assert_eq!(
            scalar_count(
                &conn,
                "SELECT COUNT(*) FROM session_events
                 WHERE provider = 'codex' AND timestamp < (
                     SELECT value FROM settings WHERE key = 'retention.watermark'
                 )",
            ),
            0,
            "watermark must block pre-cutoff Codex detail on every replay"
        );
        drop(conn);

        unsafe {
            std::env::remove_var("QUILL_CLAUDE_PROJECTS_DIR");
            std::env::remove_var("QUILL_CODEX_SESSIONS_DIR");
        }
        clear_env();
    }

    // @lat: [[backend#Backend#Database#Schema#Usage Tracking#Usage Snapshot Source Test Specs#Migration 36 Account Dimension]]
    #[test]
    #[serial]
    fn migration_36_preserves_direct_usage_and_isolates_cpa_rows() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");

        // Build a complete v35 fixture by initializing the current schema,
        // then removing only migration 36's additive surface.
        let storage = init_storage_in(&dir);
        {
            let conn = storage.conn.lock().unwrap();
            conn.execute_batch(
                "DELETE FROM schema_version WHERE version >= 36;
                 ALTER TABLE usage_snapshots DROP COLUMN source;
                 ALTER TABLE usage_snapshots DROP COLUMN account_label;
                 ALTER TABLE usage_snapshots DROP COLUMN account_id;
                 INSERT INTO usage_snapshots
                     (timestamp, provider, bucket_key, bucket_label,
                      utilization, resets_at)
                 VALUES
                     ('2026-08-01T00:00:00Z', 'claude', 'five_hour',
                      '5 hours', 25.0, NULL);",
            )
            .expect("prepare v35 usage fixture");
        }
        drop(storage);

        let migrated = init_storage_in(&dir);
        {
            let conn = migrated.conn.lock().unwrap();
            for column in ["source", "account_id", "account_label"] {
                assert!(
                    table_has_column(&conn, "usage_snapshots", column),
                    "usage_snapshots.{column} missing after migration 36"
                );
            }
            let migration_rows: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM schema_version WHERE version = 36",
                    [],
                    |row| row.get(0),
                )
                .expect("count migration 36 records");
            assert_eq!(migration_rows, 1);
        }
        let direct = migrated
            .get_latest_usage_buckets(IntegrationProvider::Claude)
            .expect("read migrated direct usage");
        assert_eq!(direct.len(), 1);
        assert_eq!(direct[0].source, UsageSource::Direct);
        assert_eq!(direct[0].account_id, None);
        assert_eq!(direct[0].account_label, None);
        drop(migrated);

        // A normal restart must skip migration 36 and reopen cleanly.
        let reopened = init_storage_in(&dir);
        {
            let conn = reopened.conn.lock().unwrap();
            let migration_rows: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM schema_version WHERE version = 36",
                    [],
                    |row| row.get(0),
                )
                .expect("count migration 36 records after reopen");
            assert_eq!(migration_rows, 1);
        }

        reopened
            .store_snapshot(&[UsageBucket {
                provider: IntegrationProvider::Claude,
                key: "cpa/17/five_hour".into(),
                label: "5 hours".into(),
                utilization: 80.0,
                resets_at: None,
                sort_order: 0,
                source: UsageSource::Cpa,
                account_id: Some("17".into()),
                account_label: Some("account@example.com".into()),
            }])
            .expect("store CPA usage snapshot");

        let direct = reopened
            .get_latest_usage_buckets(IntegrationProvider::Claude)
            .expect("read direct-only usage");
        assert_eq!(direct.len(), 1);
        assert!(
            direct
                .iter()
                .all(|bucket| bucket.source == UsageSource::Direct)
        );

        let cpa = reopened
            .get_latest_cpa_usage_buckets()
            .expect("read CPA usage");
        assert_eq!(cpa.len(), 1);
        assert_eq!(cpa[0].source, UsageSource::Cpa);
        assert_eq!(cpa[0].account_id.as_deref(), Some("17"));
        assert_eq!(cpa[0].account_label.as_deref(), Some("account@example.com"));

        {
            let conn = reopened.conn.lock().unwrap();
            conn.execute_batch(
                "INSERT INTO usage_hourly
                     (hour, provider, bucket_key, bucket_label,
                      avg_utilization, max_utilization, min_utilization,
                      sample_count)
                 VALUES
                     ('2026-07-01T00:00:00Z', 'claude',
                      'cpa/17/five_hour', '5 hours', 80.0, 80.0, 80.0, 1),
                     ('2026-07-01T00:00:00Z', 'claude',
                      'five_hour', '5 hours', 25.0, 25.0, 25.0, 1);",
            )
            .expect("seed hourly cleanup rows");
        }

        reopened
            .delete_cpa_usage_snapshots()
            .expect("delete CPA usage snapshots");
        reopened
            .set_setting("usage.cpa.window_smoke.claude", "true")
            .expect("seed CPA smoke setting");
        reopened
            .set_setting("usage.claude.last_attempt_at", "preserve")
            .expect("seed direct usage setting");
        reopened
            .delete_settings_with_prefix("usage.cpa.")
            .expect("delete CPA usage settings");
        {
            let conn = reopened.conn.lock().unwrap();
            let cpa_snapshots: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM usage_snapshots WHERE source = 'cpa'",
                    [],
                    |row| row.get(0),
                )
                .expect("count CPA snapshots");
            let cpa_hourly: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM usage_hourly
                     WHERE bucket_key LIKE 'cpa/%'",
                    [],
                    |row| row.get(0),
                )
                .expect("count CPA hourly rows");
            let direct_hourly: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM usage_hourly
                     WHERE bucket_key = 'five_hour'",
                    [],
                    |row| row.get(0),
                )
                .expect("count direct hourly rows");
            assert_eq!(cpa_snapshots, 0);
            assert_eq!(cpa_hourly, 0);
            assert_eq!(direct_hourly, 1);
        }
        assert_eq!(
            reopened
                .get_setting("usage.cpa.window_smoke.claude")
                .expect("read deleted CPA smoke setting"),
            None
        );
        assert_eq!(
            reopened
                .get_setting("usage.claude.last_attempt_at")
                .expect("read preserved direct usage setting")
                .as_deref(),
            Some("preserve")
        );

        drop(reopened);
        clear_env();
    }

    // @lat: [[backend#Backend#Database#Schema#Hourly Analytics Rollups#Rollup Migration Test Specs#Migration 37 Additive Schema]]
    #[test]
    #[serial]
    fn migration_37_adds_empty_rollup_schema_and_reopens() {
        clear_env();

        let assert_rollup_schema = |conn: &Connection| {
            for table in [
                "model_usage_hourly",
                "runtime_hourly",
                "runtime_turn_state",
                "rollup_meta",
            ] {
                assert!(
                    table_exists(conn, table),
                    "missing migration 37 table {table}"
                );
            }
            for (table, columns) in [
                (
                    "model_usage_hourly",
                    &[
                        "hour_utc",
                        "provider",
                        "derived_model_id",
                        "source_key",
                        "analytics_session_id",
                        "obs_count",
                        "turn_count",
                        "token_count",
                        "sidechain_count",
                        "input_tokens",
                        "input_tokens_present",
                        "output_tokens",
                        "output_tokens_present",
                        "cache_creation_tokens",
                        "cache_creation_tokens_present",
                        "cache_read_tokens",
                        "cache_read_tokens_present",
                        "first_observed_at_ms",
                        "last_observed_at_ms",
                        "raw_pruned",
                    ][..],
                ),
                (
                    "runtime_hourly",
                    &[
                        "hour_utc",
                        "provider",
                        "source_key",
                        "session_id",
                        "turn_count",
                        "runtime_secs",
                        "first_turn_start_ms",
                        "last_turn_end_ms",
                        "raw_pruned",
                    ][..],
                ),
                (
                    "runtime_turn_state",
                    &[
                        "provider",
                        "source_key",
                        "finalized_through_rowid",
                        "open_turn_started_ms",
                    ][..],
                ),
                (
                    "rollup_meta",
                    &[
                        "id",
                        "rollup_generation",
                        "model_backfill_status",
                        "model_backfill_done_through_ms",
                        "runtime_backfill_status",
                        "runtime_backfill_done_through_rowid",
                    ][..],
                ),
            ] {
                for column in columns {
                    assert!(
                        table_has_column(conn, table, column),
                        "{table}.{column} missing after migration 37"
                    );
                }
            }
            assert!(index_present(conn, "idx_model_usage_hourly_source"));
            assert!(index_present(conn, "idx_runtime_hourly_source"));

            let meta: (i64, String, Option<i64>, String, Option<i64>) = conn
                .query_row(
                    "SELECT rollup_generation,
                            model_backfill_status,
                            model_backfill_done_through_ms,
                            runtime_backfill_status,
                            runtime_backfill_done_through_rowid
                     FROM rollup_meta WHERE id = 1",
                    [],
                    |row| {
                        Ok((
                            row.get(0)?,
                            row.get(1)?,
                            row.get(2)?,
                            row.get(3)?,
                            row.get(4)?,
                        ))
                    },
                )
                .expect("read rollup metadata singleton");
            assert_eq!(
                meta,
                (0, "pending".into(), None, "pending".into(), None),
                "migration initializes bookmarks without doing backfill work"
            );
        };

        // Fresh databases apply migration 37 and receive the empty schema.
        let fresh_dir = TempDir::new().expect("fresh tempdir");
        let fresh = init_storage_in(&fresh_dir);
        {
            let conn = fresh.conn.lock().unwrap();
            assert_rollup_schema(&conn);
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM model_usage_hourly"),
                0
            );
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM runtime_hourly"),
                0
            );
        }
        drop(fresh);
        clear_env();

        // Build a v36 database with raw evidence, then remove only v37's
        // additive surface. Reopening must recreate the schema without folding
        // either raw table in the migration transaction.
        let existing_dir = TempDir::new().expect("existing tempdir");
        let existing = init_storage_in(&existing_dir);
        {
            let conn = existing.conn.lock().unwrap();
            conn.execute_batch(
                "INSERT INTO model_usage_observations (
                     provider, source_key, source_record_key, source_ordinal,
                     observation_kind, source_session_id,
                     analytics_session_id, chain_id, is_sidechain,
                     observed_at_ms, input_tokens, model_evidence,
                     token_evidence, derived_model_id
                 ) VALUES (
                     'claude', 'source-v36', 'record-v36', 0,
                     'token', 'session-v36', 'session-v36', 'session-v36', 0,
                     1760000000000, 42, 'explicit', 'direct', 'claude-opus'
                 );
                 INSERT INTO session_events (
                     provider, source_key, event_key, session_id, chain_id,
                     is_sidechain, timestamp, kind
                 ) VALUES (
                     'claude', 'source-v36', 'event-v36', 'session-v36',
                     'session-v36', 0, '2025-10-09T08:53:20Z', 'asst_text'
                 );
                 DROP TABLE model_usage_hourly;
                 DROP TABLE runtime_hourly;
                 DROP TABLE runtime_turn_state;
                 DROP TABLE rollup_meta;
                 DELETE FROM schema_version WHERE version >= 37;",
            )
            .expect("prepare v36 rollup fixture");
        }
        drop(existing);

        let migrated = init_storage_in(&existing_dir);
        {
            let conn = migrated.conn.lock().unwrap();
            assert_rollup_schema(&conn);
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM model_usage_observations"),
                1
            );
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM session_events"),
                1
            );
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM model_usage_hourly"),
                0
            );
            assert_eq!(
                scalar_count(&conn, "SELECT COUNT(*) FROM runtime_hourly"),
                0
            );
            assert_eq!(
                scalar_count(
                    &conn,
                    "SELECT COUNT(*) FROM schema_version WHERE version = 37"
                ),
                1
            );
        }
        drop(migrated);

        // A normal restart skips migration 37 and leaves one version record.
        let reopened = init_storage_in(&existing_dir);
        {
            let conn = reopened.conn.lock().unwrap();
            assert_rollup_schema(&conn);
            assert_eq!(
                scalar_count(
                    &conn,
                    "SELECT COUNT(*) FROM schema_version WHERE version = 37"
                ),
                1
            );
        }
        drop(reopened);
        clear_env();
    }

