    #[test]
    #[serial]
    fn observed_state_survives_audit_persistence_failure() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");
        let storage = init_storage_in(&dir);
        let state = crate::server::ObservedSubagentState::default();
        let observation = |hook_event: &str, source: Option<&str>, agent_id: Option<&str>| {
            crate::models::ObservedHookObservation {
                provider: IntegrationProvider::Codex,
                session_id: "failed-audit-root".to_string(),
                hostname: Some("host".to_string()),
                hook_event: hook_event.to_string(),
                source: source.map(str::to_owned),
                tool_name: None,
                cwd: None,
                ts: if hook_event == "SessionStart" {
                    "2030-01-01T00:00:01Z"
                } else {
                    "2030-01-01T00:00:02Z"
                }
                .to_string(),
                hook_matcher: None,
                agent_id: agent_id.map(str::to_owned),
                agent_type: None,
                model: None,
            }
        };

        state.observe(&observation("SessionStart", Some("startup"), None));
        let agent = observation("SubagentStart", None, Some("agent"));
        state.observe(&agent);
        storage
            .conn
            .lock()
            .unwrap()
            .execute_batch(
                "CREATE TRIGGER fail_hook_audit
                 BEFORE INSERT ON hook_invocations
                 BEGIN SELECT RAISE(FAIL, 'forced hook audit failure'); END;",
            )
            .expect("install audit failure trigger");

        let error = storage
            .store_hook_observation(&agent)
            .expect_err("audit persistence must fail");
        assert!(error.contains("forced hook audit failure"));
        assert_eq!(
            state.live_count("codex", "host", "failed-audit-root"),
            Some(1)
        );
    }

    fn assert_rollup_wal_bound(
        target: &str,
        before_checkpoint: &[u64],
        after_checkpoint: &[u64],
        bound_bytes: u64,
    ) {
        assert!(
            before_checkpoint.len() >= 2,
            "{target} fixture must exercise multiple chunks"
        );
        assert_eq!(
            before_checkpoint.len(),
            after_checkpoint.len(),
            "every {target} chunk must reach its checkpoint"
        );
        assert!(
            before_checkpoint
                .iter()
                .all(|wal_bytes| *wal_bytes <= bound_bytes),
            "{target} WAL exceeded {bound_bytes} bytes before checkpoint: \
             {before_checkpoint:?}"
        );
        assert!(
            after_checkpoint.iter().all(|wal_bytes| *wal_bytes == 0),
            "{target} TRUNCATE checkpoint left WAL bytes: {after_checkpoint:?}"
        );
    }

    // @lat: [[model-rollup-tests#Model Rollup Backfill Test Specs#Empty Completion And Committed Progress]]
    #[test]
    #[serial]
    fn model_rollup_backfill_completes_empty_database_with_committed_progress() {
        clear_env();
        let dir = TempDir::new().expect("tempdir");
        let storage = init_storage_in(&dir);
        let observer_path = storage.db_path.clone();
        let observed_statuses = Mutex::new(Vec::<String>::new());
        let observe = |_progress: &crate::rollup_backfill::RollupBackfillProgress| {
            let observer = Connection::open(&observer_path).expect("open progress observer");
            let status = observer
                .query_row(
                    "SELECT model_backfill_status FROM rollup_meta WHERE id = 1",
                    [],
                    |row| row.get::<_, String>(0),
                )
                .expect("read committed lifecycle before progress");
            observed_statuses.lock().unwrap().push(status);
        };
        let controls = RollupBackfillControls {
            progress: Some(&observe),
            ..RollupBackfillControls::default()
        };

        let started = Instant::now();
        let report = storage
            .run_model_rollup_backfill_with_controls(&controls)
            .expect("empty model rollup backfill");
        let elapsed = started.elapsed();
        eprintln!(
            "model_rollup_empty.elapsed_ms={:.3}",
            elapsed.as_secs_f64() * 1_000.0
        );
        assert_eq!(report.terminal, RollupBackfillTerminal::Completed);
        assert_eq!(
            (report.progress.rows_done, report.progress.rows_total),
            (0, 0)
        );
        assert_eq!(observed_statuses.into_inner().unwrap(), vec!["complete"]);
        assert!(
            elapsed < Duration::from_secs(1),
            "empty database should not pay corpus-scale startup overhead"
        );
        clear_env();
    }

